import { useEffect, useState, type FormEvent, type KeyboardEvent, type MouseEvent } from 'react'
import { Link, useNavigate, useParams, useSearchParams } from 'react-router'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { hubApi } from './api'
type Page<T> = { items: T[]; nextCursor: string | null; hasMore: boolean }
type Connection = { id: string; publicId: string; platformCode: string; environment: string; displayName: string; externalStoreId: string; status: string; apiVersion: string; lastTestedAt: string | null; lastSuccessAt: string | null; lastErrorCode: string | null; hasCredential: boolean; version: number }
type Capability = { code: string; supportLevel: string; sourceUrl: string | null; verifiedAt: string | null; constraintsJson: string | null; evidenceNote: string | null; version: number }
type OrderLine = { id: string; sku: string; barcode: string | null; title: string; orderedQuantity: number; cancelledQuantity: number; shippedQuantity: number; deliveredQuantity: number; returnedQuantity: number; unitPrice: number; vatRate: number; rawStatus: string; variantId: string | null; modelCode: string | null; optionSignature: string | null; imageUrl: string | null }
type Order = { id: string; orderNumber: string; derivedStatus: string; currency: string; grossAmount: number; discountAmount: number; netAmount: number; orderedAt: string; lineCount: number; packageCount: number; version: number; connectionId: string | null; platformCode: string; platformDisplayName: string; customerName: string; customerEmail: string | null; customerTaxOrIdentityNumber: string | null; orderType: string; isMicroExport: boolean; shipmentAddressJson: string; invoiceAddressJson: string; shipmentDueAt: string | null; isDeadlineCritical: boolean; invoiceStatus: string; invoiceId: string | null; invoiceDocumentUrl: string | null; cargoProviderName: string | null; cargoTrackingNumber: string | null; primaryImageUrl: string | null; productQuantity: number; lines: OrderLine[] | null; packages: Shipment[] | null }
type OrderFilters = { search: string; status: string; platform: string; listing: string; cargo: string; invoice: string; dateFrom: string; dateTo: string }
type InvoiceViewer = { id: string; orderNumber: string; invoiceType: string; status: string; currency: string; payableTotal: number; taxTotal: number; invoiceNumber: string | null; lines: Array<{ id: string; description: string; sku: string | null; unit: string; quantity: number; vatRate: number; lineTotal: number }>; documents: Array<{ id: string; documentType: string; sha256: string }> }
const initialOrderFilters: OrderFilters = { search: '', status: 'ALL', platform: 'ALL', listing: 'ALL', cargo: 'ALL', invoice: 'ALL', dateFrom: '', dateTo: '' }
async function loadAllOrders(): Promise<Page<Order>> {
  const items: Order[] = []; const seenCursors = new Set<string>(); let after: string | null = null
  while (true) {
    const params = new URLSearchParams({ limit: '200' }); if (after) params.set('after', after)
    const page = await hubApi<Page<Order>>(`/orders?${params}`); items.push(...page.items)
    if (!page.hasMore) return { items, nextCursor: null, hasMore: false }
    if (!page.nextCursor || seenCursors.has(page.nextCursor)) throw new Error('Sipariş listesinin devam sayfası güvenli biçimde alınamadı.')
    seenCursors.add(page.nextCursor); after = page.nextCursor
  }
}
type OrderDetail = { id: string; orderNumber: string; derivedStatus: string; currency: string; grossAmount: number; discountAmount: number; netAmount: number; orderedAt: string; connectionId: string | null; platformCode: string; platformDisplayName: string; customerName: string; customerEmail: string | null; customerPhone: string | null; customerTaxOrIdentityNumber: string | null; orderType: string; isMicroExport: boolean; isEInvoiceAvailable: boolean | null; shipmentAddressJson: string; invoiceAddressJson: string; shipmentDueAt: string | null; invoiceStatus: string; invoiceDocumentUrl: string | null; lines: OrderLine[]; packages: Shipment[]; version: number }
type CreatedInvoice = { id: string; version: number }
type InvoiceOperation = CreatedInvoice & { status: string; invoiceNumber: string | null; externalReference: string | null; lastErrorCode: string | null }
type Shipment = { id: string; orderId: string; orderNumber: string; externalPackageId: string; status: string; rawStatus: string; cargoTrackingNumber: string | null; cargoProviderName: string | null; statusOccurredAt: string; version: number }
type ShipmentDetail = { package: Shipment; allowedActions: string[]; supportedLabelFormats: string[]; isStageConnection: boolean; documents: Array<{ id: string; documentKind: string; format: string; source: string; documentVersion: number; createdAt: string; expiresAt: string | null }> }
type ReturnClaim = { id: string; externalClaimId: string; orderNumber: string; status: string; rawStatus: string; reasonText: string | null; actionDueAt: string | null; version: number; customerName: string; orderedAt: string | null; orderAmount: number; currency: string; cargoProviderName: string | null; cargoTrackingNumber: string | null; primaryImageUrl: string | null; productCount: number; primaryBarcode: string | null; lines: OrderLine[] | null; packageNumber: string | null; invoiceStatus: string; grossAmount: number; discountAmount: number }
type ReturnLine = { id: string; externalLineId: string; orderLineId: string; sku: string; barcode: string | null; title: string; quantity: number; disposedQuantity: number; remainingQuantity: number; unitPrice: number; imageUrl: string | null; hasInventoryMapping: boolean }; type ReturnDetail = Omit<ReturnClaim, 'lines'> & { reasonCode: string | null; allowedActions: string[]; lines: ReturnLine[] | null; stockDispositionAvailable: boolean }; type ReturnIssueReason = { id: string; name: string; evidenceRequired: boolean }
type LocalCategory = { id: string; name: string; path: string; depth: number; isLeaf: boolean; isActive: boolean; version: number }
type LocalBrand = { id: string; name: string; isActive: boolean; version: number }
type LocalAttribute = { id: string; code: string; name: string; dataType: string; isActive: boolean; version: number; values: { id: string; value: string; isActive: boolean }[] }
type CategoryRequirementView = { attributeId: string; isRequired: boolean; allowsCustomValue: boolean; displayOrder: number; attribute: LocalAttribute }
type ReferenceItem = { externalId: string; parentExternalId: string | null; name: string; path: string; depth: number; isLeaf: boolean; isActive: boolean; isRequired: boolean | null; allowsCustomValue: boolean | null; allowsMultipleValues: boolean | null }
type ReferenceData = { snapshotId: string; resourceType: string; fetchedAt: string; items: ReferenceItem[] }
type CatalogMapping = { id: string; connectionId: string; snapshotId: string; localId: string; scopeExternalId: string; externalId: string; status: string; verifiedAt: string | null; version: number }
type SearchOption = { value: string; label: string; description?: string }

function SearchableSelect({ label, value, options, placeholder, disabled = false, onChange }: { label: string; value: string; options: SearchOption[]; placeholder: string; disabled?: boolean; onChange: (value: string) => void }) {
  const selected = options.find(option => option.value === value)
  const [query, setQuery] = useState(selected?.label ?? '')
  const [open, setOpen] = useState(false)
  useEffect(() => { setQuery(selected?.label ?? '') }, [selected?.label])
  const normalized = query.trim().toLocaleLowerCase('tr-TR')
  const filtered = options.filter(option => !normalized || `${option.label} ${option.description ?? ''}`.toLocaleLowerCase('tr-TR').includes(normalized)).slice(0, normalized ? 500 : 100)
  function choose(option: SearchOption) { onChange(option.value); setQuery(option.label); setOpen(false) }
  function keyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') setOpen(false)
    if (event.key === 'Enter' && open && filtered.length) { event.preventDefault(); choose(filtered[0]) }
  }
  const listId = `search-select-${label.toLocaleLowerCase('tr-TR').replace(/[^a-z0-9]+/g, '-')}`
  return <label className={`searchable-select${open ? ' open' : ''}${disabled ? ' disabled' : ''}`}><span>{label}</span><div className="searchable-select-control"><span aria-hidden="true">⌕</span><input role="combobox" aria-label={label} aria-controls={listId} aria-expanded={open} aria-autocomplete="list" value={query} placeholder={placeholder} disabled={disabled} onFocus={() => setOpen(true)} onClick={() => setOpen(true)} onKeyDown={keyDown} onChange={event => { setQuery(event.target.value); if (value) onChange(''); setOpen(true) }} onBlur={() => window.setTimeout(() => setOpen(false), 120)} /><button type="button" tabIndex={-1} aria-label={`${label} seçeneklerini göster`} disabled={disabled} onMouseDown={event => event.preventDefault()} onClick={() => setOpen(current => !current)}>⌄</button></div>{open && <div id={listId} className="searchable-select-menu" role="listbox">{filtered.length ? filtered.map(option => <button type="button" role="option" aria-selected={option.value === value} key={option.value} onMouseDown={event => { event.preventDefault(); choose(option) }}><strong>{option.label}</strong>{option.description && <small>{option.description}</small>}</button>) : <span className="searchable-select-empty">Eşleşen kayıt bulunamadı.</span>}</div>}</label>
}
function MappingViewTabs({ active }: { active: 'category' | 'brand' }) {
  return <nav className="mapping-view-tabs" aria-label="Eşleştirme türü" role="tablist"><Link role="tab" aria-selected={active === 'category'} className={active === 'category' ? 'active' : ''} to="/mappings/categories"><span>Kategori</span><small>Kategori ve özellik yapısı</small></Link><Link role="tab" aria-selected={active === 'brand'} className={active === 'brand' ? 'active' : ''} to="/mappings/categories?view=brands"><span>Marka</span><small>Marka kimliği eşleştirmesi</small></Link></nav>
}
function idempotency() { return crypto.randomUUID() }
function wait(milliseconds: number) { return new Promise(resolve => window.setTimeout(resolve, milliseconds)) }
function displayAttributeName(value: string) { return value.replace(/\[(?:A-)?TDG\][\s_-]*/gi, '').replace(/^\(?(?:A-)?TDG\)?[\s_-]*/gi, '').replace(/_/g, ' ').replace(/\s+/g, ' ').trim() }
function ErrorBox({ error }: { error: unknown }) { return <div role="alert" className="error">{error instanceof Error ? error.message : 'İşlem tamamlanamadı.'}</div> }
function Busy({ text = 'Veriler yükleniyor…' }: { text?: string }) { return <div className="status inline" role="status"><div className="spinner" /><strong>{text}</strong></div> }
function Empty({ children }: { children: string }) { return <div className="empty"><strong>Kayıt yok</strong><p>{children}</p></div> }
function Badge({ value }: { value: string }) { const tone = value === 'SUPPORTED' || value === 'ACTIVE' || value === 'DELIVERED' || value === 'APPROVED' ? 'good' : value === 'UNKNOWN' || value === 'DRAFT' || value === 'VERIFIED' ? 'warn' : 'neutral'; return <span className={`badge ${tone}`}>{value}</span> }
function DateText({ value }: { value: string | null }) { return <>{value ? new Date(value).toLocaleString('tr-TR') : '—'}</> }

function usableShipmentDueAt(value: string | null) { if (!value) return null; const timestamp = new Date(value).getTime(); return Number.isFinite(timestamp) && timestamp >= Date.UTC(2000, 0, 1) ? value : null }
function remainingText(value: string | null) { if (!value) return 'Termin bilgisi gelmedi'; const ms = new Date(value).getTime() - Date.now(); if (ms <= 0) return 'Süre doldu'; const hours = Math.ceil(ms / 3_600_000); return hours < 48 ? `${hours} saat kaldı` : `${Math.ceil(hours / 24)} gün kaldı` }
function safeJson(value: string) { try { return JSON.parse(value || '{}') as Record<string, unknown> } catch { return {} } }
function meaningfulText(value: unknown): value is string { return typeof value === 'string' && /[\p{L}\p{N}]/u.test(value) }
function customerText(value: string) { return meaningfulText(value) ? value : 'Trendyol müşteri bilgisini maskeledi' }
function addressText(value: string) { const source = safeJson(value); const data = [source.shipmentAddress, source.invoiceAddress, source.address].find(item => item && typeof item === 'object') as Record<string, unknown> | undefined ?? source; const parts = ['fullAddress', 'address1', 'address2', 'neighborhood', 'district', 'countyName', 'city', 'countryCode', 'postalCode'].map(key => data[key]).filter(meaningfulText); return parts.length ? [...new Set(parts)].join(' · ') : 'Trendyol adres bilgisini maskeledi' }
function optionRows(value: string | null) { const parts = (value ?? '').split(/[|,·;]+/).map(item => item.trim()).filter(Boolean); const fields = parts.map(part => { const match = part.match(/^([^:=-]+)\s*[:=-]\s*(.+)$/); return match ? { label: match[1].trim(), value: match[2].trim() } : null }).filter((item): item is { label: string; value: string } => item !== null); return fields.length ? fields : value ? [{ label: 'Seçenek', value }] : [] }
function longDate(value: string) { return new Intl.DateTimeFormat('tr-TR', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) }
function deliveryText(item: Order) { const shipment = item.packages?.[0]; if (item.derivedStatus === 'CANCELLED') return { label: 'İptal tarihi', value: shipment?.statusOccurredAt ? longDate(shipment.statusOccurredAt) : 'İptal zamanı bekleniyor', note: null, overdue: false }; if (item.derivedStatus === 'DELIVERED') return { label: 'Teslim edildi', value: shipment?.statusOccurredAt ? longDate(shipment.statusOccurredAt) : 'Teslimat zamanı bekleniyor', note: null, overdue: false }; if (item.derivedStatus === 'SHIPPED') return { label: 'Taşıma durumunda', value: shipment?.statusOccurredAt ? longDate(shipment.statusOccurredAt) : 'Kargo zamanı bekleniyor', note: 'Bugün kargoya verildi', overdue: false }; const dueAt = usableShipmentDueAt(item.shipmentDueAt); const due = dueAt ? new Date(dueAt).getTime() : Number.NaN; const overdueDays = Number.isFinite(due) ? Math.floor((Date.now() - due) / 86_400_000) : 0; if (overdueDays > 0) return { label: '', value: `Siparişiniz ${overdueDays} gün gecikmiştir!`, note: 'Siparişinizi en kısa sürede kargoya teslim etmelisiniz.', overdue: true }; return { label: 'Kalan süre', value: dueAt ? remainingText(dueAt) : item.isMicroExport ? 'Trendyol termin bilgisi göndermedi' : 'Termin zamanı bekleniyor', note: null, overdue: false } }
function InvoiceInfoModal({ item, onClose }: { item: Order; onClose: () => void }) {
  const detail = useQuery({ queryKey: ['invoice-info-order', item.id], queryFn: () => hubApi<OrderDetail>(`/orders/${item.id}`) })
  const order = detail.data
  return <div className="workspace-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="workspace-modal invoice-info-modal" role="dialog" aria-modal="true" aria-labelledby="invoice-info-title" onMouseDown={event => event.stopPropagation()}><header><h2 id="invoice-info-title">Fatura &amp; Adres Bilgileri</h2><button type="button" className="modal-close" onClick={onClose} aria-label="Pencereyi kapat">×</button></header>{detail.isLoading ? <Busy text="Fatura ve adres bilgileri API’den yükleniyor…" /> : detail.isError || !order ? <ErrorBox error={detail.error} /> : <><div className="invoice-address-sheet"><section><h3>Teslimat Adresi</h3><dl><dt>Ad-soyad:</dt><dd>{order.customerName}</dd><dt>Adres:</dt><dd>{addressText(order.shipmentAddressJson)}</dd></dl></section><section><h3>Fatura Adresi</h3><dl><dt>Ad-soyad:</dt><dd>{order.customerName}</dd><dt>Adres:</dt><dd>{addressText(order.invoiceAddressJson)}</dd><dt>E-Fatura Mükellefi:</dt><dd>{order.isEInvoiceAvailable === null ? 'Bilgi gelmedi' : order.isEInvoiceAvailable ? 'Evet' : 'Hayır'}</dd></dl></section><section className="invoice-contact"><dl><dt>E-posta Adresi:</dt><dd>{order.customerEmail ?? 'Bilgi gelmedi'}</dd><dt>Telefon Numarası:</dt><dd>{order.customerPhone ?? 'Bilgi gelmedi'}</dd></dl></section><p>Faturanızı <strong>Fatura işlemleri</strong> altındaki <strong>Fatura Yükle</strong> alanına PDF, JPEG, JPG veya PNG biçiminde ekleyebilirsiniz. Entegratörle çalışıyorsanız fatura bağlantısını bu alandan takip edebilirsiniz.</p></div><footer><button type="button" className="secondary" onClick={onClose}>Vazgeç</button><button type="button" onClick={() => window.print()}>Yazdır</button></footer></>}</section></div>
}

function InvoiceDraftModal({ item, provider, onClose }: { item: Order; provider: Connection | null; onClose: () => void }) {
  const client = useQueryClient()
  const [message, setMessage] = useState('')
  const [created, setCreated] = useState(false)
  const [refreshQueued, setRefreshQueued] = useState(false)
  const [activeInvoiceId, setActiveInvoiceId] = useState(item.invoiceId)
  const detail = useQuery({ queryKey: ['invoice-draft-order', item.id], queryFn: () => hubApi<OrderDetail>(`/orders/${item.id}`), refetchInterval: query => refreshQueued && !query.state.data?.packages?.length ? 3000 : false })
  const order = detail.data
  const packageId = order?.packages[0]?.id
  useEffect(() => { if (refreshQueued && packageId) { setRefreshQueued(false); setMessage('Paket bilgisi geldi. Faturayı oluşturabilirsiniz.') } }, [packageId, refreshQueued])
  useEffect(() => {
    if (!refreshQueued || packageId) return
    const timeout = window.setTimeout(() => {
      setRefreshQueued(false)
      setMessage('Paket bilgisi hâlâ gelmedi. Trendyol paketi oluşturduğunda fatura oluşturma açılacaktır.')
    }, 12000)
    return () => window.clearTimeout(timeout)
  }, [packageId, refreshQueued])
  const refreshOrder = useMutation({
    mutationFn: () => {
      if (!order?.connectionId) throw new Error('Siparişin Trendyol bağlantısı bulunamadı.')
      return hubApi(`/connections/${order.connectionId}/order-sync-jobs`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify({ externalOrderId: order.orderNumber }) })
    },
    onSuccess: async () => { setRefreshQueued(true); setMessage('Sipariş ve paket bilgisi yenileme kuyruğa alındı. Paket geldiğinde fatura oluşturma düğmesi açılacak.'); await client.invalidateQueries({ queryKey: ['invoice-draft-order', item.id] }); await client.invalidateQueries({ queryKey: ['orders'] }) },
    onError: error => setMessage(error instanceof Error ? error.message : 'Sipariş bilgisi yenilenemedi.')
  })
  const create = useMutation({
    mutationFn: async () => {
      if (!order || !packageId || !provider?.hasCredential) throw new Error('Aktif ve yetkili Trendyol E-Faturam bağlantısı gereklidir.')
      let invoice = activeInvoiceId
        ? await hubApi<InvoiceOperation>(`/invoices/${activeInvoiceId}`)
        : await hubApi<InvoiceOperation>('/invoices', { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify({ orderId: order.id, packageId, providerConnectionId: provider.id, originalInvoiceId: null }) })
      setActiveInvoiceId(invoice.id)
      if (invoice.status === 'DRAFT' || invoice.status === 'VALIDATION_FAILED')
        invoice = await hubApi<InvoiceOperation>(`/invoices/${invoice.id}/validate`, { method: 'POST', headers: { 'If-Match': `"v${invoice.version}"` } })
      const canRetryPreProviderFailure = !invoice.externalReference && ((invoice.status === 'REJECTED' && ['EFATURAM_FISCAL_PAYLOAD_INVALID', 'EFATURAM_REQUEST_REJECTED', 'EFATURAM_APPLICATION_NOT_ACTIVE'].includes(invoice.lastErrorCode ?? '')) || (invoice.status === 'SUBMITTING' && ['EFATURAM_AUTHENTICATION_FAILED', 'EFATURAM_ACCESS_TOKEN_REJECTED', 'EFATURAM_INVOICE_CREATE_PRIVILEGE_MISSING'].includes(invoice.lastErrorCode ?? '')))
      if (invoice.status === 'READY' || canRetryPreProviderFailure) {
        await hubApi(`/invoices/${invoice.id}/submit-jobs`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${invoice.version}"` }, body: JSON.stringify({ password: '', confirmed: false }) })
        invoice = await hubApi<InvoiceOperation>(`/invoices/${invoice.id}`)
      }
      for (let attempt = 0; attempt < 30 && invoice.status === 'SUBMITTING'; attempt++) {
        await wait(1000)
        invoice = await hubApi<InvoiceOperation>(`/invoices/${invoice.id}`)
      }
      if (['SUBMITTED', 'ACCEPTED', 'MARKETPLACE_PENDING', 'COMPLETED'].includes(invoice.status)) return invoice
      if (invoice.status === 'SUBMITTING') throw new Error('Fatura E-Faturam’a gönderildi; sağlayıcı yanıtı henüz bekleniyor.')
      if (invoice.lastErrorCode === 'EFATURAM_ACCESS_TOKEN_REJECTED') throw new Error('E-Faturam oturum anahtarını reddetti. Canlı E-Faturam bağlantısını ve hesap yetkisini kontrol edin.')
      if (invoice.lastErrorCode === 'EFATURAM_APPLICATION_NOT_ACTIVE') throw new Error('E-Faturam, gönderen hesabın Stage fatura uygulamasını aktif görmüyor. Bu hesap için E-Arşiv API hizmetinin sağlayıcı tarafından etkinleştirilmesi gerekiyor.')
      throw new Error(invoice.lastErrorCode ? `E-Faturam faturayı oluşturamadı: ${invoice.lastErrorCode}` : `E-Faturam faturası oluşturulamadı (${invoice.status}).`)
    },
    onSuccess: async invoice => {
      setCreated(true)
      setMessage(invoice.invoiceNumber ? `Fatura E-Faturam’da oluşturuldu: ${invoice.invoiceNumber}` : 'Fatura E-Faturam’da başarıyla oluşturuldu.')
      await client.invalidateQueries({ queryKey: ['orders'] })
      await client.invalidateQueries({ queryKey: ['invoice-draft-order', item.id] })
      window.setTimeout(onClose, 1400)
    },
    onError: error => setMessage(error instanceof Error ? error.message : 'Fatura oluşturulamadı.')
  })
  const money = (value: number) => value.toLocaleString('tr-TR', { style: 'currency', currency: order?.currency ?? item.currency })
  return <div className="workspace-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="workspace-modal invoice-draft-modal" role="dialog" aria-modal="true" aria-labelledby="invoice-draft-title" onMouseDown={event => event.stopPropagation()}><header><div><h2 id="invoice-draft-title">Fatura Oluştur</h2><p>#{item.orderNumber} siparişi için fatura bilgilerini kontrol edin.</p></div><button type="button" className="modal-close" onClick={onClose} aria-label="Pencereyi kapat">×</button></header>{detail.isLoading ? <Busy text="Müşteri, adres ve ürün bilgileri API’den yükleniyor…" /> : detail.isError || !order ? <ErrorBox error={detail.error} /> : <><div className="invoice-draft-notice"><span aria-hidden="true">i</span><div><strong>Faturanız Trendyol E-Faturam sağlayıcısında oluşturulacaktır.</strong><p>Müşteri, fatura adresi, ürün, miktar ve vergi bilgileri Trendyol sipariş snapshot’ından alınır. Fatura oluşturulduğunda önce mali olarak doğrulanır, ardından E-Faturam’a gönderilir. Bağlantı, credential, tekrar koruması ve sağlayıcı yanıt kontrolü korunur.</p></div></div><div className="invoice-draft-customer"><span><small>Müşteri / unvan</small><strong>{customerText(order.customerName)}</strong></span><span><small>TC / vergi no</small><strong>{meaningfulText(order.customerTaxOrIdentityNumber) ? order.customerTaxOrIdentityNumber : 'Trendyol bu bilgiyi maskeledi'}</strong></span><span><small>Fatura adresi</small><strong>{addressText(order.invoiceAddressJson)}</strong></span></div><div className="invoice-draft-table" role="table"><div className="invoice-draft-head" role="row"><strong>Ürün Bilgisi</strong><strong>KDV Oranı</strong><strong>KDV Tutarı</strong><strong>Miktar</strong><strong>Birim Fiyatı</strong><strong>Toplam Tutar</strong></div>{order.lines.map(line => { const total = line.unitPrice * line.orderedQuantity; const vat = total * line.vatRate / (100 + line.vatRate); return <div role="row" key={line.id}><span><strong>{line.title}</strong><small>{line.sku}{line.modelCode ? ` · Model ${line.modelCode}` : ''}</small></span><span>%{line.vatRate}</span><span>{money(vat)}</span><span>{line.orderedQuantity} adet</span><span>{money(line.unitPrice)}</span><strong>{money(total)}</strong></div> })}</div><div className="invoice-draft-total"><span>İndirim <strong>{money(order.discountAmount)}</strong></span><span>Fatura toplamı <strong>{money(order.netAmount)}</strong></span></div>{!packageId && <div className="invoice-draft-recovery notice" role="status"><span>Bu siparişin paket bilgisi henüz gelmedi. Fatura paket oluşmadan oluşturulamaz.</span><button type="button" className="secondary" disabled={refreshOrder.isPending || refreshQueued || !order.connectionId} onClick={() => refreshOrder.mutate()}>{refreshOrder.isPending || refreshQueued ? 'Paket bilgisi yenileniyor…' : 'Paket bilgisini yenile'}</button></div>}{!provider?.hasCredential && <div role="alert" className="error invoice-draft-message">Aktif ve yetkili Trendyol E-Faturam bağlantısı gereklidir.</div>}{message && <div role="status" className={`notice invoice-draft-message ${created ? 'invoice-created-feedback' : ''}`}>{message}</div>}<footer><button type="button" className="secondary" onClick={onClose}>Vazgeç</button>{!created && <button type="button" className="invoice-continue" disabled={create.isPending || !packageId || !provider?.hasCredential} onClick={() => create.mutate()}>{create.isPending ? 'Fatura oluşturuluyor…' : 'Faturayı Oluştur'}</button>}</footer></>}</section></div>
}

function InvoiceViewerModal({ item, onClose }: { item: Order; onClose: () => void }) {
  const invoiceId = item.invoiceId
  const detail = useQuery({ queryKey: ['invoice-viewer', invoiceId], queryFn: () => hubApi<InvoiceViewer>(`/invoices/${invoiceId}`), enabled: !!invoiceId })
  const invoice = detail.data
  return <div className="workspace-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="workspace-modal invoice-viewer-modal" role="dialog" aria-modal="true" aria-labelledby="invoice-viewer-title" onMouseDown={event => event.stopPropagation()}><header><div><h2 id="invoice-viewer-title">Fatura Görüntüle</h2><p>#{item.orderNumber} · {invoice?.invoiceNumber ?? 'Numara bekleniyor'}</p></div><button type="button" className="modal-close" onClick={onClose} aria-label="Pencereyi kapat">×</button></header>{detail.isLoading ? <Busy text="Fatura yükleniyor…" /> : detail.isError || !invoice ? <ErrorBox error={detail.error} /> : <><div className="invoice-viewer-summary"><span><small>Durum</small><strong>{invoice.status}</strong></span><span><small>Fatura tipi</small><strong>{invoice.invoiceType}</strong></span><span><small>Ödenecek</small><strong>{invoice.payableTotal.toLocaleString('tr-TR', { style: 'currency', currency: invoice.currency })}</strong></span><span><small>Vergi</small><strong>{invoice.taxTotal.toLocaleString('tr-TR', { style: 'currency', currency: invoice.currency })}</strong></span></div><div className="invoice-viewer-lines" role="table"><div className="invoice-viewer-line invoice-viewer-line-head" role="row"><strong>Ürün</strong><strong>Miktar</strong><strong>KDV</strong><strong>Toplam</strong></div>{invoice.lines.map(line => <div className="invoice-viewer-line" role="row" key={line.id}><span><strong>{line.description}</strong><small>{line.sku ?? 'Stok kodu yok'}</small></span><span>{line.quantity} {line.unit}</span><span>%{line.vatRate}</span><strong>{line.lineTotal.toLocaleString('tr-TR', { style: 'currency', currency: invoice.currency })}</strong></div>)}</div>{invoice.documents.length ? <div className="invoice-viewer-documents"><strong>Belgeler</strong>{invoice.documents.map(document => <a key={document.id} href={`/api/v1/invoices/${invoice.id}/documents/${document.id}/content`} target="_blank" rel="noreferrer">{document.documentType === 'PDF' ? 'PDF faturayı aç' : 'Fatura belgesini aç'} ↗</a>)}</div> : <p className="invoice-viewer-empty">Provider belgesi henüz arşivlenmedi.</p>}<footer><button type="button" className="secondary" onClick={onClose}>Kapat</button><button type="button" onClick={() => window.print()}>Yazdır</button></footer></>}</section></div>
}

function InvoiceUploadModal({ item, provider, onClose }: { item: Order; provider: Connection | null; onClose: () => void }) {
  const client = useQueryClient()
  const [file, setFile] = useState<File | null>(null)
  const [message, setMessage] = useState('')
  const [dragging, setDragging] = useState(false)
  const detail = useQuery({ queryKey: ['invoice-upload-order', item.id], queryFn: () => hubApi<OrderDetail>(`/orders/${item.id}`) })
  const upload = useMutation({
    mutationFn: async () => {
      if (!file) throw new Error('Yüklenecek fatura dosyasını seçin.')
      if (file.size > 10 * 1024 * 1024) throw new Error('Fatura dosyası en fazla 10 MB olabilir.')
      if (!/\.(pdf|jpe?g|png)$/i.test(file.name)) throw new Error('Yalnız PDF, JPEG, JPG veya PNG dosyası yükleyebilirsiniz.')
      const order = detail.data
      if (!order) throw new Error('Sipariş bilgileri henüz yüklenmedi.')
      let invoiceId = item.invoiceId
      if (!invoiceId) {
        const packageId = order.packages[0]?.id
        if (!packageId || !provider?.hasCredential) throw new Error('Fatura taslağı için aktif ve yetkili Trendyol E-Faturam bağlantısı gereklidir.')
        const invoice = await hubApi<CreatedInvoice>('/invoices', { method: 'POST', headers: { 'Idempotency-Key': `invoice:${order.id}:${packageId}` }, body: JSON.stringify({ orderId: order.id, packageId, providerConnectionId: provider.id, originalInvoiceId: null }) })
        invoiceId = invoice.id
      }
      const form = new FormData(); form.append('file', file)
      await hubApi(`/invoices/${invoiceId}/documents/manual`, { method: 'POST', headers: { 'Idempotency-Key': `invoice-document:${invoiceId}:${file.name}:${file.size}:${file.lastModified}` }, body: form })
    },
    onSuccess: async () => { await client.invalidateQueries({ queryKey: ['orders'] }); onClose() },
    onError: error => setMessage(error instanceof Error ? error.message : 'Fatura dosyası yüklenemedi.')
  })
  function choose(selected: File | undefined) { if (selected) { setFile(selected); setMessage('') } }
  return <div className="workspace-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="workspace-modal invoice-upload-modal" role="dialog" aria-modal="true" aria-labelledby="invoice-upload-title" onMouseDown={event => event.stopPropagation()}><header><h2 id="invoice-upload-title">Fatura Yükle</h2><button type="button" className="modal-close" onClick={onClose} aria-label="Pencereyi kapat">×</button></header>{detail.isError ? <ErrorBox error={detail.error} /> : <><label className={`invoice-dropzone${dragging ? ' dragging' : ''}`} onDragEnter={event => { event.preventDefault(); setDragging(true) }} onDragOver={event => event.preventDefault()} onDragLeave={() => setDragging(false)} onDrop={event => { event.preventDefault(); setDragging(false); choose(event.dataTransfer.files[0]) }}><input type="file" accept=".pdf,.jpeg,.jpg,.png,application/pdf,image/jpeg,image/png" onChange={event => choose(event.target.files?.[0])} /><span className="invoice-upload-icon" aria-hidden="true">⇧</span><strong>{file ? file.name : 'Fatura Dosyası Yükle'}</strong><small>{file ? `${(file.size / 1024 / 1024).toFixed(2)} MB` : 'Dosyanızı seçin ya da bu alana sürükleyin.'}</small><b>Dosya Seç</b></label>{message && <p className="error" role="alert">{message}</p>}<footer><button type="button" className="secondary" onClick={onClose}>Vazgeç</button><button type="button" disabled={!file || detail.isLoading || upload.isPending} onClick={() => upload.mutate()}>{upload.isPending ? 'Yükleniyor…' : 'Faturayı Yükle'}</button></footer></>}</section></div>
}

function CourierChangeModal({ item, onClose }: { item: Order; onClose: () => void }) {
  const carriers = ['Yurtiçi Kargo', 'Sürat Kargo', 'DHL eCommerce', 'PTT Kargo', 'Kolay Gelsin', 'Aras Kargo', 'Horoz Kargo', 'CEVA Logistics']
  return <div className="workspace-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="workspace-modal courier-change-modal" role="dialog" aria-modal="true" aria-labelledby="courier-change-title" onMouseDown={event => event.stopPropagation()}><header><div><h2 id="courier-change-title">Paketi hangi firma ile göndermek istiyorsunuz?</h2><p>Seçilen kargo firması için fiyat ve uygunluk bilgisi, işlem açılmadan önce doğrulanır.</p></div><button type="button" className="modal-close" onClick={onClose} aria-label="Pencereyi kapat">×</button></header><p className="courier-description"><strong>#{item.orderNumber}</strong> numaralı paket için kargo firması değişikliği şu anda yalnız ön izleme modunda gösterilir; hiçbir dış işlem başlatılmaz.</p><h3>Standart Kargo Firmaları <span>(0–30 desi)</span></h3><div className="courier-options">{carriers.map(carrier => <label key={carrier}><input type="radio" name="courier" disabled /><span>{carrier}</span></label>)}</div><footer><button type="button" className="secondary" onClick={onClose}>Vazgeç</button><button type="button" disabled>İşlemi Yap</button></footer></section></div>
}

function OrderReferenceRow({ item, selected, onSelect, openMenu, onMenuChange, onInvoiceCreate, onInvoiceDetails, onInvoiceUpload, onCourierChange }: { item: Order; selected: boolean; onSelect: (checked: boolean) => void; openMenu: 'invoice' | 'actions' | null; onMenuChange: (value: 'invoice' | 'actions' | null) => void; onInvoiceCreate: () => void; onInvoiceDetails: () => void; onInvoiceUpload: () => void; onCourierChange: () => void }) {
  const lines = item.lines ?? []
  const shipment = item.packages?.[0]
  const invoiceCreationStatuses = ['FATURA_BEKLIYOR', 'FATURA_REDDEDILDI', 'FATURA_ISLENIYOR']
  const invoiceNeedsAction = invoiceCreationStatuses.includes(item.invoiceStatus)
  const [copied, setCopied] = useState(false)
  const [menuPlacement, setMenuPlacement] = useState<'down' | 'up'>('down')
  const [previewImage, setPreviewImage] = useState<{ url: string; title: string } | null>(null)
  const money = (value: number) => value.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })
  const delivery = deliveryText(item)
  async function copyOrderNumber() { try { await navigator.clipboard.writeText(item.orderNumber); setCopied(true); window.setTimeout(() => setCopied(false), 1400) } catch { setCopied(false) } }
  function toggleMenu(kind: 'invoice' | 'actions', event: MouseEvent<HTMLButtonElement>) {
    if (openMenu === kind) { onMenuChange(null); return }
    const trigger = event.currentTarget.getBoundingClientRect()
    const estimatedHeight = kind === 'invoice' ? 150 : 132
    const availableBelow = window.innerHeight - trigger.bottom
    setMenuPlacement(availableBelow >= estimatedHeight + 12 ? 'down' : 'up')
    onMenuChange(kind)
  }
  return <article className={`order-reference-row ${item.derivedStatus.toLowerCase()} ${item.isMicroExport ? 'micro-export' : ''} ${openMenu ? 'menu-open' : ''}`}>
    <div className="order-reference-grid">
      <label className="order-select"><input type="checkbox" checked={selected} onChange={event => onSelect(event.target.checked)} aria-label={`Sipariş ${item.orderNumber} seç`} /></label>
      <div className="order-reference-meta"><div className="order-number"><strong><i className="order-package-mark" aria-hidden="true" />#{item.orderNumber}</strong><button type="button" className="order-number-copy" onClick={copyOrderNumber} aria-label={`Sipariş numarası ${item.orderNumber} kopyala`} title={copied ? 'Kopyalandı' : 'Sipariş numarasını kopyala'}><span className="copy-icon" aria-hidden="true" /></button></div><small>Sipariş Tarihi: <DateText value={item.orderedAt} /></small><small>Paket No: {shipment?.externalPackageId ?? 'Bekleniyor'}</small><small>Teslimat No: {shipment?.cargoTrackingNumber ?? 'Bekleniyor'}</small><span className={delivery.overdue ? 'delivery-overdue' : ''}>{delivery.label && <>{delivery.label}: </>}<b>{delivery.value}</b>{delivery.note && <em>{delivery.note}</em>}</span></div>
      <div className="order-reference-buyer"><strong>{item.customerName}</strong></div>
      <div className="order-reference-products">{lines.length ? lines.map(line => { const imageUrl = line.imageUrl ?? item.primaryImageUrl; return <article key={line.id}><span className="reference-product-media">{imageUrl ? <button type="button" className="product-image-button" onClick={() => setPreviewImage({ url: imageUrl, title: line.title })} aria-label={`${line.title} görselini büyüt`}><img src={imageUrl} alt={`${line.title} ürün görseli`} /></button> : <span className="reference-product-placeholder" aria-label="Ürün görseli eşleştirmesi bekleniyor">▧</span>}<b className="quantity-bubble">{line.orderedQuantity}</b></span><div><strong>{line.title}</strong><small>Stok Kodu: {line.sku}</small>{optionRows(line.optionSignature).map(option => <small key={`${option.label}:${option.value}`}>{option.label}: {option.value}</small>)}<small>Barkod: {line.barcode ?? '—'}</small><small>Model Kodu: {line.modelCode ?? '—'}</small></div></article> }) : <div className="reference-no-product">Ürün bilgisi eşitleme bekliyor</div>}</div>
      <div className="order-reference-prices">{lines.length ? lines.map(line => <strong key={line.id}>{money(line.unitPrice)}</strong>) : <strong>{money(item.netAmount)}</strong>}</div>
      <div className="order-reference-cargo"><strong>{shipment?.cargoProviderName ?? item.cargoProviderName ?? 'Kargo bekleniyor'}</strong><b>{shipment?.cargoTrackingNumber ?? item.cargoTrackingNumber ?? 'Takip no bekleniyor'}</b></div>
      <div className={`order-reference-invoice ${item.invoiceStatus === 'FATURA_BEKLIYOR' ? 'invoice-pending' : 'invoice-created'}`}><small>Satış Tutarı:</small><strong>{money(item.grossAmount || item.netAmount)}</strong>{item.discountAmount > 0 && <small>Satıcı İndirim Tutarı: {money(item.discountAmount)}</small>}{item.isMicroExport && <span className="micro-invoice-chip">Mikro İhracat Faturası</span>}{invoiceNeedsAction && <span>{item.invoiceStatus === 'FATURA_BEKLIYOR' ? 'Fatura bekleniyor' : item.invoiceStatus === 'FATURA_ISLENIYOR' ? 'Fatura kontrol ediliyor' : 'Fatura reddedildi'}</span>}{!invoiceNeedsAction && (item.invoiceId ? <a className="invoice-document-link" href={`/api/v1/invoices/${item.invoiceId}/documents/latest/content`} download>Faturayı Gör</a> : item.invoiceDocumentUrl ? <a className="invoice-document-link" href={item.invoiceDocumentUrl} download>Faturayı Gör</a> : null)}<div className="row-menu"><button type="button" className="row-menu-trigger" onClick={event => toggleMenu('invoice', event)} aria-expanded={openMenu === 'invoice'}><span>Fatura işlemleri</span><b aria-hidden="true">⌄</b></button>{openMenu === 'invoice' && <div className={`row-popover invoice-popover opens-${menuPlacement}`} role="menu">{invoiceNeedsAction ? <><button type="button" role="menuitem" className="create-invoice" onClick={onInvoiceCreate}>Fatura Oluştur</button><button type="button" role="menuitem" onClick={onInvoiceDetails}>Fatura Bilgileri</button><button type="button" role="menuitem" onClick={onInvoiceUpload}>Fatura Yükle</button></> : <>{item.invoiceId ? <a role="menuitem" className="invoice-menu-view" href={`/api/v1/invoices/${item.invoiceId}/documents/latest/content`} download>Fatura Görüntüle</a> : item.invoiceDocumentUrl ? <a role="menuitem" className="invoice-menu-view" href={item.invoiceDocumentUrl} download>Fatura Görüntüle</a> : null}<button type="button" role="menuitem" onClick={onInvoiceDetails}>Fatura Bilgileri</button><button type="button" role="menuitem" className="destructive" disabled>Fatura İptal Et</button></>}</div>}</div></div>
      <div className="order-reference-actions">{item.derivedStatus === 'SHIPPED' && shipment?.cargoTrackingNumber ? <><Link className="cargo-track-action" to={`/shipments/${shipment.id}`}>Kargo Takip</Link><span className="cargo-action-unavailable">İşlem Yapılamaz</span></> : shipment?.cargoTrackingNumber ? <><Link to={`/shipments/${shipment.id}`}>Kargo Etiketini A4 Yazdır</Link><Link to={`/shipments/${shipment.id}`} title="Trendyol ortak etiket çıktısı ZPL olarak desteklendiğinde açılır">Kargo Etiketini Sticker Yazdır</Link></> : <span>Etiket için takip numarası bekleniyor</span>}<div className="row-menu"><button type="button" className="order-action-menu row-menu-trigger" onClick={event => toggleMenu('actions', event)} aria-expanded={openMenu === 'actions'}>İşlemler⌄</button>{openMenu === 'actions' && <div className={`row-popover action-popover opens-${menuPlacement}`} role="menu">{shipment ? <Link to={`/shipments/${shipment.id}`} role="menuitem">İşleme Al</Link> : <button type="button" disabled>İşleme Al</button>}<button type="button" role="menuitem" onClick={onCourierChange}>Başka Kargo Firması İle Gönder</button><button type="button" role="menuitem" disabled>İptal Et</button></div>}</div></div>
    </div>{previewImage && <div className="workspace-modal-backdrop product-image-backdrop" role="presentation" onMouseDown={() => setPreviewImage(null)}><section className="workspace-modal product-image-modal" role="dialog" aria-modal="true" aria-label={`${previewImage.title} büyük ürün görseli`} onMouseDown={event => event.stopPropagation()}><header><h2>{previewImage.title}</h2><button type="button" className="modal-close" onClick={() => setPreviewImage(null)} aria-label="Pencereyi kapat">×</button></header><img src={previewImage.url} alt={`${previewImage.title} büyük ürün görseli`} /></section></div>}
  </article>
}
function returnGroup(status: string) { const value = status.toUpperCase(); if (['APPROVED', 'COMPLETED'].includes(value)) return 'APPROVED'; if (['REJECTED', 'CANCELLED'].includes(value)) return 'REJECTED'; if (['REQUESTED', 'CREATED'].includes(value)) return 'REQUESTED'; if (['ACTION_REQUIRED', 'WAITING_FOR_SELLER_ACTION'].includes(value)) return 'ACTION_REQUIRED'; if (['WAITING_FOR_SHIPMENT', 'IN_TRANSIT', 'RETURN_IN_TRANSIT', 'SHIPPED'].includes(value)) return 'SHIPPING'; if (value === 'DISPUTED') return 'DISPUTED'; if (['SUSPENDED', 'ON_HOLD'].includes(value)) return 'SUSPENDED'; return 'REVIEW' }
const activePlatformCodes = new Set(['TRENDYOL', 'TRENDYOL_EFATURAM'])
function credentialLabel(item: Connection) { return item.platformCode === 'TRENDYOL_EFATURAM' && item.lastErrorCode === 'EFATURAM_CONFIGURATION_UNAVAILABLE' ? 'Yenileme gerekli' : item.hasCredential ? 'Şifreli kayıtlı' : 'Bekleniyor' }
function credentialHelp(item: Connection) { return item.platformCode === 'TRENDYOL_EFATURAM' && item.lastErrorCode === 'EFATURAM_CONFIGURATION_UNAVAILABLE' ? 'E-Faturam hesap e-postası ve parolasıyla şifreli kaydı yenileyin.' : item.hasCredential ? 'Şifreli kaydedildi; değerler tekrar gösterilmez.' : 'Credential kaydı bekleniyor.' }
function connectionTestHelp(item: Connection) {
  if (item.platformCode === 'TRENDYOL_EFATURAM' && item.lastErrorCode === 'EFATURAM_ACCESS_TOKEN_REJECTED') return 'Giriş başarılı; sağlayıcı sign-in yanıtındaki taze JWT tokenını korumalı fatura API’sinde geçersiz veya süresi dolmuş olarak reddetti.'
  return item.lastErrorCode ?? 'Hata kaydı yok'
}

function InlineConnectionCard({ item, onSaved }: { item: Connection; onSaved: () => void }) {
  const efaturam = item.platformCode === 'TRENDYOL_EFATURAM'
  const [notice, setNotice] = useState('')
  const [environment, setEnvironment] = useState(item.environment)
  const save = useMutation({ mutationFn: (body: object) => hubApi(`/connections/${item.id}/credential`, { method: 'PUT', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${item.version}"` }, body: JSON.stringify(body) }), onSuccess: () => { setNotice('Bilgiler kaydedildi.'); onSaved() }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Bağlantı bilgileri kaydedilemedi.') })
  const update = useMutation({ mutationFn: (value: string) => hubApi(`/connections/${item.id}`, { method: 'PATCH', headers: { 'If-Match': `"v${item.version}"` }, body: JSON.stringify({ displayName: item.displayName, environment: value }) }), onSuccess: () => { setNotice('Ortam güncellendi.'); onSaved() }, onError: reason => { setEnvironment(item.environment); setNotice(reason instanceof Error ? reason.message : 'Ortam güncellenemedi.') } })
  const test = useMutation({ mutationFn: () => hubApi<{ succeeded?: boolean; errorCode?: string; errorSummary?: string }>(`/connections/${item.id}/test-jobs`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: '{}' }), onSuccess: result => { setNotice(result.succeeded ? 'Bağlantı testi başarılı.' : `Bağlantı testi başarısız${result.errorCode ? `: ${result.errorCode}` : '.'}`); onSaved() }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Bağlantı testi başlatılamadı.') })
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); save.mutate(efaturam ? { email: data.get('email'), password: data.get('password') } : { apiKey: data.get('apiKey'), apiSecret: data.get('apiSecret') }) }
  function changeEnvironment(value: string) { setEnvironment(value); if (value !== item.environment) update.mutate(value) }
  const connected = item.status === 'ACTIVE' || item.status === 'VERIFIED'
  const testResult = item.lastErrorCode ? `Son test başarısız: ${item.lastErrorCode}` : item.lastSuccessAt ? 'Son test başarılı; bağlantı kullanılabilir.' : item.lastTestedAt ? 'Son test sonucu bekleniyor.' : ''
 return <form className="integration-card integration-card-form" onSubmit={submit}><div className="integration-card-top"><span className={`platform-mark ${item.platformCode.toLowerCase()}`}>{efaturam ? '▤' : '◉'}</span><span className={connected ? 'connection-state connected' : 'connection-state'}><i />{connected ? 'Bağlı' : 'Bağlı değil'}</span></div><h2>{item.displayName}</h2><p>{efaturam ? 'Fatura sağlayıcısı' : 'Sipariş kaynağı'}</p><div className="integration-fields"><label>Ortam<select value={environment} onChange={event => changeEnvironment(event.target.value)} disabled={update.isPending}><option value="STAGE">Stage</option><option value="PRODUCTION">Canlı</option></select></label><label>{efaturam ? 'Yerel bağlantı kapsamı' : 'Mağaza kimliği'}<input value={item.externalStoreId} readOnly /></label>{efaturam ? <><label>Hesap e-postası<input name="email" type="email" autoComplete="username" placeholder={item.hasCredential ? 'Kayıtlı hesabı değiştirmek için girin' : 'ornek@firma.com'} required /></label><label>Hesap parolası<input name="password" type="password" autoComplete="new-password" placeholder="Parolanızı girin" required /></label></> : <><label>Servis anahtarı<input name="apiKey" type="password" autoComplete="off" placeholder={item.hasCredential ? 'Kayıtlı anahtarı değiştirmek için girin' : 'API key'} required /></label><label>Servis gizli anahtarı<input name="apiSecret" type="password" autoComplete="new-password" placeholder="API secret" required /></label></>}</div>{testResult && <div role="status" className={`integration-test-result ${item.lastErrorCode ? 'failed' : 'success'}`}>{testResult}{item.lastTestedAt && <small> · {new Date(item.lastTestedAt).toLocaleString('tr-TR')}</small>}</div>}{notice && <div role="status" className="integration-card-notice">{notice}</div>}<div className="integration-card-actions"><button type="button" className="secondary" onClick={() => test.mutate()} disabled={test.isPending || save.isPending}>{test.isPending ? 'Kontrol ediliyor…' : 'Bağlantıyı kontrol et'}</button><button type="submit" className="connection-button" disabled={save.isPending}>{save.isPending ? 'Kaydediliyor…' : connected ? 'Bağlandı ✓' : 'Bağlan'}</button></div></form>
}

export function IntegrationsPage() {
  const client = useQueryClient()
  const [createOpen, setCreateOpen] = useState(false)
  const [createPlatform, setCreatePlatform] = useState('TRENDYOL')
  const [createError, setCreateError] = useState('')
  const query = useQuery({ queryKey: ['connections'], queryFn: () => hubApi<Page<Connection>>('/connections') })
  const activeConnections = query.data?.items.filter(item => activePlatformCodes.has(item.platformCode)) ?? []
  const create = useMutation({ mutationFn: (body: object) => hubApi('/connections', { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify(body) }), onSuccess: () => { setCreateOpen(false); setCreateError(''); void client.invalidateQueries({ queryKey: ['connections'] }) }, onError: reason => setCreateError(reason instanceof Error ? reason.message : 'Bağlantı oluşturulamadı.') })
  function submitCreate(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); create.mutate({ displayName: data.get('displayName'), environment: data.get('environment'), externalStoreId: data.get('externalStoreId'), platformCode: createPlatform, apiVersion: createPlatform === 'TRENDYOL' ? 'V2' : '1.0.0', userAgentIdentity: createPlatform === 'TRENDYOL' ? data.get('userAgentIdentity') : null }) }
  return <section className="content f3"><div className="page-heading"><div><p className="eyebrow">Platformlar</p><h1>Entegrasyonlar</h1><p className="lede">Her platform için gerekli giriş bilgilerini bu ekrandan kaydedin; bağlantı başarılı olduğunda sipariş ve fatura akışları aktifleşir.</p></div></div>
    {query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : <><div className="integration-grid">{activeConnections.map(item => <InlineConnectionCard item={item} onSaved={() => { void client.invalidateQueries({ queryKey: ['connections'] }) }} key={item.id} />)}{activeConnections.length < 3 && <button type="button" className="integration-card integration-card-empty" aria-label="Yeni bağlantı ekle" onClick={() => setCreateOpen(true)}><span className="integration-add-icon" aria-hidden="true">+</span></button>}</div>{!activeConnections.length && <Empty>Henüz aktif bağlantı bulunmuyor.</Empty>}{createOpen && <div className="integration-modal-backdrop" role="presentation" onMouseDown={() => setCreateOpen(false)}><form className="integration-modal" onSubmit={submitCreate} onMouseDown={event => event.stopPropagation()}><div className="integration-modal-header"><h2>Yeni bağlantı</h2><button type="button" className="modal-close" onClick={() => setCreateOpen(false)} aria-label="Pencereyi kapat">×</button></div><label>Platform<select value={createPlatform} onChange={event => setCreatePlatform(event.target.value)}><option value="TRENDYOL">Trendyol</option><option value="TRENDYOL_EFATURAM">Trendyol E-Faturam</option></select></label><label>Bağlantı adı<input name="displayName" placeholder="Örn. Trendyol Canlı" required /></label><label>Ortam<select name="environment" defaultValue="STAGE"><option value="STAGE">Stage</option><option value="PRODUCTION">Canlı</option></select></label><label>{createPlatform === 'TRENDYOL' ? 'Mağaza kimliği' : 'Yerel bağlantı kapsamı'}<input name="externalStoreId" placeholder={createPlatform === 'TRENDYOL' ? 'Mağaza ID' : 'Ravencia - Ravencia'} required /></label>{createPlatform === 'TRENDYOL' && <label>User-Agent kimliği<input name="userAgentIdentity" placeholder="Firma - Entegrasyon" required /></label>}{createError && <div role="alert" className="integration-card-notice">{createError}</div>}<button type="submit" className="connection-button" disabled={create.isPending}>{create.isPending ? 'Oluşturuluyor…' : 'Bağlantıyı oluştur'}</button></form></div>}</>}
  </section>
}

function IntegrationDetailWorkspace({ id, inline = false }: { id: string; inline?: boolean }) {
  const client = useQueryClient(); const [notice, setNotice] = useState(''); const connection = useQuery({ queryKey: ['connection', id], queryFn: () => hubApi<Connection>(`/connections/${id}`) }); const capabilities = useQuery({ queryKey: ['capabilities', id], queryFn: () => hubApi<Capability[]>(`/connections/${id}/capabilities`) });
  const run = useMutation({ mutationFn: (request: { path: string; body?: object; version?: number }) => hubApi(request.path, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), ...(request.version ? { 'If-Match': `"v${request.version}"` } : {}) }, body: JSON.stringify(request.body ?? {}) }), onSuccess: () => { setNotice('İş kuyruğa alındı.'); void client.invalidateQueries({ queryKey: ['connection', id] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'İşlem tamamlanamadı.') })
  function refreshSingleOrder(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const orderNumber = String(new FormData(event.currentTarget).get('orderNumber') ?? '').trim(); if (orderNumber) run.mutate({ path: `/connections/${id}/order-sync-jobs`, body: { externalOrderId: orderNumber } }) }
  const activate = useMutation({ mutationFn: (version: number) => hubApi<Connection>(`/connections/${id}/active`, { method: 'PUT', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${version}"` }, body: JSON.stringify({ active: true }) }), onSuccess: () => { setNotice('Bağlantı etkinleştirildi.'); void client.invalidateQueries({ queryKey: ['connection', id] }); void client.invalidateQueries({ queryKey: ['connections'] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Bağlantı etkinleştirilemedi.') })
  async function settings(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!connection.data) return; const data = new FormData(event.currentTarget); try { const body = { displayName: data.get('displayName'), userAgentIdentity: data.get('userAgentIdentity') }; await hubApi<Connection>(`/connections/${id}`, { method: 'PATCH', headers: { 'If-Match': `"v${connection.data.version}"` }, body: JSON.stringify(body) }); setNotice('Bağlantı ayarları güncellendi.'); await client.invalidateQueries({ queryKey: ['connection', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Bağlantı ayarları güncellenemedi.') } }
  async function credential(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!connection.data) return; const data = new FormData(event.currentTarget); const body = connection.data.platformCode === 'TRENDYOL_EFATURAM' ? { email: data.get('email') || null, password: data.get('password') || null } : { apiKey: data.get('apiKey'), apiSecret: data.get('apiSecret') }; try { await hubApi(`/connections/${id}/credential`, { method: 'PUT', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${connection.data.version}"` }, body: JSON.stringify(body) }); setNotice('Credential şifreli olarak yenilendi; değerler tekrar gösterilmeyecek.'); await client.invalidateQueries({ queryKey: ['connection', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Credential kaydedilemedi.') } }
  async function evidence(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); const code = String(data.get('code') || ''); const capability = capabilities.data?.find(value => value.code === code); if (!capability) return; try { const constraints = String(data.get('constraintsJson') || '').trim(); await hubApi(`/connections/${id}/capabilities/${encodeURIComponent(code)}/evidence`, { method: 'PUT', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `\"v${capability.version}\"` }, body: JSON.stringify({ supportLevel: data.get('supportLevel'), sourceUrl: data.get('sourceUrl'), sourceVersion: data.get('sourceVersion'), environment: item.environment, storeScope: item.externalStoreId, evidenceNote: data.get('evidenceNote'), fixtureChecksum: data.get('fixtureChecksum') || null, constraintsJson: constraints || null, verifiedAt: new Date(String(data.get('verifiedAt'))).toISOString() }) }); setNotice('Capability kanıtı audit kaydıyla güncellendi.'); await client.invalidateQueries({ queryKey: ['capabilities', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Capability kanıtı kaydedilemedi.') } }
  const rootClass = inline ? 'integration-inline-workspace' : 'content f3'
  if (connection.isLoading) return <div className={rootClass}><Busy /></div>; if (connection.isError || !connection.data) return <div className={rootClass}><ErrorBox error={connection.error} /></div>; const item = connection.data
  if (!activePlatformCodes.has(item.platformCode)) return <div className={rootClass}><Link to="/integrations" className="back">← Platformlar</Link><div className="unknown"><strong>Bağlantı aktif kapsam dışında</strong><p>ADR-016 uyarınca panel yalnız Trendyol ve Trendyol E-Faturam ile ilerler. Kapsam dışı tarihsel bağlantılara işlem sunulmaz.</p></div></div>
  const stageManual = item.environment === 'STAGE'; const stageReady = stageManual && !item.lastErrorCode && (item.status === 'ACTIVE' || item.status === 'VERIFIED'); const orderReadSupported = item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE' && (stageManual || capabilities.data?.some(cap => cap.code === 'ORDER_READ' && cap.supportLevel === 'SUPPORTED') === true); const referenceReadSupported = item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE' && (stageManual || capabilities.data?.some(cap => cap.code === 'REFERENCE_READ' && cap.supportLevel === 'SUPPORTED') === true)
  return <div className={rootClass}><div className="page-heading"><div><Link to="/integrations" className="back">← Platformlar</Link><h1>{item.displayName}</h1><p className="lede">{item.environment} · {item.platformCode === 'TRENDYOL_EFATURAM' ? 'yerel kapsam' : 'mağaza'} {item.externalStoreId} · API {item.apiVersion}</p></div><Badge value={item.status} /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="grid"><article><small>Credential</small><strong>{credentialLabel(item)}</strong><p>{credentialHelp(item)}</p></article><article><small>Son test</small><strong><DateText value={item.lastTestedAt} /></strong><p>{connectionTestHelp(item)}</p></article><article><small>{stageManual ? 'Stage işlemleri' : 'Dış yazma'}</small><strong>{stageManual ? stageReady ? 'Hazır' : 'Bloke' : 'Kapalı'}</strong><p>{stageManual ? stageReady ? 'Manuel denemeler aktif bağlantı, credential ve teknik doğrulamalarla çalışır; sağlayıcı yanıtı iş sonucunu belirler.' : 'Son korumalı bağlantı testi başarısız. Sağlayıcı erişimi düzeltilmeden fatura gönderimi başlatılmaz.' : 'Production yazmaları master ve bağlantı anahtarlarıyla korunur.'}</p></article></div>
    {item.platformCode === 'TRENDYOL' && item.status === 'VERIFIED' && <div className="panel"><h2>Bağlantıyı etkinleştir</h2><p>Başarılı bağlantı testi kanıtı korunarak yalnız bu Trendyol bağlantısı etkinleştirilir. Dış yazmalar kapalı kalır.</p><button disabled={activate.isPending} onClick={() => activate.mutate(item.version)}>{activate.isPending ? 'Etkinleştiriliyor…' : 'Bağlantıyı ACTIVE yap'}</button></div>}
    {orderReadSupported && <div className="panel"><h2>Salt-okunur sipariş eşitleme</h2><p>{stageManual ? 'Aktif Stage bağlantısından siparişleri okuyup yerel kaydı günceller. Bu işlem dış platforma yazmaz.' : 'Doğrulanmış sipariş okuma desteğiyle platform siparişlerini yerel kayda alır. Bu işlem dış platforma yazmaz.'}</p><div className="button-row"><button disabled={run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/order-sync-jobs`, body: { externalOrderId: null } })}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Siparişleri eşitle'}</button></div><form className="inline-form" onSubmit={refreshSingleOrder}><label>Sipariş numarasıyla yenile<input name="orderNumber" inputMode="numeric" pattern="[0-9]+" placeholder="Örn. 1238693012" required /></label><button className="secondary" disabled={run.isPending}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Yalnız bu siparişi yenile'}</button></form></div>}
    {item.platformCode === 'TRENDYOL' && item.environment === 'STAGE' && item.externalStoreId === '2738' && <div className="panel"><h2>Taze Stage test siparişi</h2><p>Yalnız resmî Stage seller 2738 test barkoduyla tek denemelik fixture oluşturur. Production ve normal dış yazma anahtarları kullanılmaz.</p><button disabled={run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/stage-test-order-jobs` })}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Taze Stage test siparişi oluştur'}</button></div>}
    {referenceReadSupported && <div className="panel"><h2>Salt-okunur katalog referansları</h2><p>{stageManual ? 'Aktif Stage bağlantısından kategori ve marka listelerini yerel snapshot olarak günceller. Trendyol’a yazmaz.' : 'Doğrulanmış referans okuma desteğiyle kategori ve marka listelerini yerel snapshot olarak günceller. Trendyol’a yazmaz.'}</p><div className="button-row"><button disabled={run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/reference-sync-jobs?resourceType=CATEGORIES` })}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Kategorileri eşitle'}</button><button className="secondary" disabled={run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/reference-sync-jobs?resourceType=BRANDS` })}>{run.isPending ? 'Kuyruğa alınıyor…' : 'Markaları eşitle'}</button><Link className="button-link secondary" to="/mappings/categories?view=brands">Marka eşlemelerine git</Link></div></div>}
    {item.platformCode === 'TRENDYOL' && <form className="panel form-panel" onSubmit={settings}><h2>Bağlantı ayarları</h2><label>Bağlantı adı<input name="displayName" defaultValue={item.displayName} required /></label><label>User-Agent kimliği<input name="userAgentIdentity" placeholder="Firma-Adı - Entegrasyon-Adı" autoComplete="off" required /></label><button>Bağlantı ayarlarını kaydet</button></form>}
    {item.platformCode === 'TRENDYOL_EFATURAM' && <article className="panel"><h2>E-Faturam hesap yetkisi</h2><p>Fatura API'si bağlı bireysel E-Faturam hesabının oturumunu kullanır. Firma ve kullanıcı kimliği yalnız sağlayıcının erişim tokenından alınır; panelde gösterilmez veya ayar olarak saklanmaz.</p><div className="card-list"><div className="record-card"><span><strong>Belge türü</strong><small>Kurumsal ve E-Fatura mükellefi: TEMELFATURA; diğer siparişler: EARSIVFATURA</small></span><Badge value="AUTO" /></div><div className="record-card"><span><strong>İnternet satışı ek alanları</strong><small>Kullanıcı ayarı değildir; gerekli olduğunda Trendyol siparişi ve resmî kargo kataloğundan otomatik hazırlanır.</small></span><Badge value="AUTO" /></div></div></article>}
    <div className="split"><form className="panel form-panel" onSubmit={credential}><h2>Credential döndür</h2>{item.platformCode === 'TRENDYOL_EFATURAM' ? <><label>Hesap e-postası<input name="email" type="email" autoComplete="username" required /></label><label>Hesap parolası<input name="password" type="password" autoComplete="new-password" required /></label><p>Bu alanlar yalnız şifreli credential kaydında tutulur ve tekrar gösterilmez.</p></> : <><label>API key<input name="apiKey" type="password" autoComplete="off" required /></label><label>API secret<input name="apiSecret" type="password" autoComplete="new-password" required /></label></>}<button disabled={run.isPending}>Şifreli kaydet</button><button type="button" className="secondary" disabled={!item.hasCredential || run.isPending} onClick={() => run.mutate({ path: `/connections/${id}/test-jobs` })}>Bağlantıyı test et</button></form>
      {stageManual ? <div className="panel"><h2>Stage operasyon durumu</h2><p>Manuel testler capability kanıtı eksikliği nedeniyle durmaz. Bağlantı, credential, girdi doğrulaması, tekrar koruması ve sağlayıcı yanıt doğrulaması korunur.</p><p>Teknik kanıt ve ayrıntılı hata kayıtları İşlem Takibi’nde tutulur.</p></div> : <div className="panel"><h2>Capability kanıtları</h2>{capabilities.isLoading ? <Busy /> : capabilities.isError ? <ErrorBox error={capabilities.error} /> : <div className="capability-list">{capabilities.data?.map(cap => <div key={cap.code}><span><strong>{cap.code}</strong><small><DateText value={cap.verifiedAt} /></small>{cap.evidenceNote && <small className="capability-note">{cap.evidenceNote}</small>}</span><Badge value={cap.supportLevel} /></div>)}</div>}</div>}</div>
    {!stageManual && capabilities.data?.length ? <form className="panel form-panel" onSubmit={evidence}><h2>Capability kanıtı kaydet</h2><p>Production write capability için resmî kanıt kaydı zorunludur.</p><label>Capability<select name="code">{capabilities.data.map(cap => <option key={cap.code}>{cap.code}</option>)}</select></label><label>Destek seviyesi<select name="supportLevel" defaultValue="UNKNOWN"><option>UNKNOWN</option><option>SUPPORTED</option><option>NOT_SUPPORTED</option></select></label><label>Resmî kaynak URL<input name="sourceUrl" type="url" placeholder="https://developers.trendyol.com veya developers.trendyolefaturam.com/..." required /></label><label>Kaynak sürümü<input name="sourceVersion" defaultValue="V2" required /></label><label>Doğrulama zamanı<input name="verifiedAt" type="datetime-local" required /></label><label>Kanıt notu<textarea name="evidenceNote" maxLength={1000} required /></label><label>Stage/SIT fixture SHA-256<input name="fixtureChecksum" minLength={64} maxLength={64} /></label><label>Kısıtlar JSON<textarea name="constraintsJson" placeholder='{"allowedActions":["PICKING","TRACKING_NUMBER"]}' /></label><button>Kanıtı kaydet</button></form> : null}
  </div>
}

export function IntegrationDetailPage() {
  const { id = '' } = useParams()
  return <IntegrationDetailWorkspace id={id} />
}

export function OrdersPage() {
  const client = useQueryClient()
  const [searchParams, setSearchParams] = useSearchParams(); const [filterForm, setFilterForm] = useState<OrderFilters>(initialOrderFilters); const [filters, setFilters] = useState<OrderFilters>(initialOrderFilters); const [advancedFilters, setAdvancedFilters] = useState(false); const [pageSize, setPageSize] = useState(50); const [page, setPage] = useState(1); const [selectedIds, setSelectedIds] = useState<string[]>([]); const [menu, setMenu] = useState<{ orderId: string; kind: 'invoice' | 'actions' } | null>(null); const [bulkOpen, setBulkOpen] = useState(false); const [bulkNotice, setBulkNotice] = useState(''); const [invoiceInfoOrder, setInvoiceInfoOrder] = useState<Order | null>(null); const [invoiceViewerOrder, setInvoiceViewerOrder] = useState<Order | null>(null); const [invoiceDraftOrder, setInvoiceDraftOrder] = useState<Order | null>(null); const [invoiceUploadOrder, setInvoiceUploadOrder] = useState<Order | null>(null); const [courierOrder, setCourierOrder] = useState<Order | null>(null)
  const query = useQuery({ queryKey: ['orders'], queryFn: loadAllOrders })
  const connections = useQuery({ queryKey: ['connections', 'orders-invoice'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const providers = connections.data?.items.filter(x => x.platformCode === 'TRENDYOL_EFATURAM' && !x.lastErrorCode && (x.status === 'ACTIVE' || x.status === 'VERIFIED')) ?? []
  const provider = providers.find(x => x.environment === 'PRODUCTION') ?? providers.find(x => x.environment === 'STAGE') ?? null
  const statuses = [['ALL', 'Tümü'], ['NEW', 'Yeni'], ['PROCESSING', 'İşleme Alınanlar'], ['SHIPPED', 'Kargoda'], ['DELIVERED', 'Teslim Edildi'], ['CANCELLED', 'İptal']] as const
  const all = query.data?.items ?? []; const normalized = filters.search.trim().toLocaleLowerCase('tr-TR')
  const cargos = Array.from(new Set(all.map(item => item.packages?.[0]?.cargoProviderName ?? item.cargoProviderName).filter((value): value is string => !!value)))
  const platforms = Array.from(new Set(all.map(item => item.platformCode).filter(Boolean)))
  const updateFilter = <K extends keyof OrderFilters>(key: K, value: OrderFilters[K]) => setFilterForm(current => ({ ...current, [key]: value }))
  const applyFilters = () => { setFilters(filterForm); setPage(1) }
  const clearFilters = () => { setFilterForm(initialOrderFilters); setFilters(initialOrderFilters); setPage(1) }
  const selectStatus = (status: string) => { const next = { ...filterForm, status }; setFilterForm(next); setFilters(current => ({ ...current, status })); setPage(1) }
  const items = all.filter(item => {
    const searchValues = [item.orderNumber, item.customerName, item.customerEmail ?? '', item.customerTaxOrIdentityNumber ?? '', item.cargoTrackingNumber ?? '', ...(item.packages ?? []).flatMap(pack => [pack.externalPackageId, pack.cargoTrackingNumber ?? '', pack.cargoProviderName ?? '']), ...(item.lines ?? []).flatMap(line => [line.title, line.sku, line.barcode ?? '', line.modelCode ?? '', line.optionSignature ?? ''])]
    const ordered = new Date(item.orderedAt); const from = filters.dateFrom ? new Date(`${filters.dateFrom}T00:00:00`) : null; const to = filters.dateTo ? new Date(`${filters.dateTo}T23:59:59.999`) : null; const isClosed = ['DELIVERED', 'CANCELLED'].includes(item.derivedStatus.toUpperCase())
    return (filters.status === 'ALL' || item.derivedStatus.toUpperCase() === filters.status) && (filters.platform === 'ALL' || item.platformCode === filters.platform) && (filters.listing === 'ALL' || (filters.listing === 'OPEN' ? !isClosed : isClosed)) && (filters.cargo === 'ALL' || (item.packages?.[0]?.cargoProviderName ?? item.cargoProviderName) === filters.cargo) && (filters.invoice === 'ALL' || item.invoiceStatus === filters.invoice) && (!from || ordered >= from) && (!to || ordered <= to) && (!normalized || searchValues.some(value => value.toLocaleLowerCase('tr-TR').includes(normalized)))
  })
  const totalPages = Math.max(1, Math.ceil(items.length / pageSize)); const safePage = Math.min(page, totalPages); const pageItems = items.slice((safePage - 1) * pageSize, safePage * pageSize); const allPageSelected = pageItems.length > 0 && pageItems.every(item => selectedIds.includes(item.id))
  useEffect(() => { const invoiceId = searchParams.get('invoice'); if (!invoiceId || !all.length) return; const item = all.find(order => order.invoiceId === invoiceId); if (!item) return; setInvoiceViewerOrder(item); setSearchParams(current => { const next = new URLSearchParams(current); next.delete('invoice'); return next }, { replace: true }) }, [all, searchParams, setSearchParams])
  function updateSelection(id: string, checked: boolean) { setSelectedIds(current => checked ? Array.from(new Set([...current, id])) : current.filter(value => value !== id)) }
  function togglePageSelection(checked: boolean) { setSelectedIds(current => checked ? Array.from(new Set([...current, ...pageItems.map(item => item.id)])) : current.filter(id => !pageItems.some(item => item.id === id))) }
  const selectedOrders = all.filter(item => selectedIds.includes(item.id))
  async function bulkAction(kind: 'processing' | 'courier' | 'invoice' | 'labels') {
    setBulkOpen(false)
    if (kind === 'processing') {
      const eligible = selectedOrders.filter(item => item.derivedStatus.toUpperCase() === 'NEW' && item.packages?.length)
      if (!eligible.length) { setBulkNotice('Seçimde işleme alınabilecek yeni sipariş bulunmuyor.'); return }
      if (!window.confirm(`${eligible.length} yeni sipariş Trendyol’da “İşleme Al” durumuna geçirilecek. Devam edilsin mi?`)) return
      try {
        for (const item of eligible) { const pack = item.packages![0]; await hubApi(`/shipments/${pack.id}/actions`, { method: 'POST', headers: { 'Idempotency-Key': `bulk-picking:${pack.id}:${pack.version}`, 'If-Match': `"v${pack.version}"` }, body: JSON.stringify({ action: 'PICKING', payloadJson: '{}' }) }) }
        setBulkNotice(`${eligible.length} sipariş için “İşleme Al” işleri güvenli kuyruğa alındı; sonuçlar eşitleme sonrasında doğrulanacak.`)
        setSelectedIds([])
        await client.invalidateQueries({ queryKey: ['orders'] })
      } catch (error) { setBulkNotice(error instanceof Error ? error.message : 'Toplu işleme alma tamamlanamadı.') }
      return
    }
    if (kind === 'courier') { const first = selectedOrders.find(item => item.packages?.length); if (first) setCourierOrder(first); else setBulkNotice('Seçimde kargo paketi bulunan sipariş yok.'); return }
    if (kind === 'invoice') { const first = selectedOrders.find(item => item.invoiceStatus === 'FATURA_BEKLIYOR'); if (first) setInvoiceDraftOrder(first); else setBulkNotice('Seçimde fatura bekleyen sipariş yok.'); return }
    const printable = selectedOrders.filter(item => item.packages?.[0]?.cargoTrackingNumber)
    setBulkNotice(printable.length ? `${printable.length} siparişin kargo stickerı yazdırılabilir. Etiketler paket ve takip bilgileriyle hazırlanır.` : 'Seçimde takip numarası bulunan sipariş yok.')
  }
  return <section className="content f3 orders-page"><div className="page-heading"><div><p className="eyebrow">Sipariş yönetimi</p><h1>Siparişler</h1><p className="lede">Sipariş, müşteri, ürün, termin, fatura ve kargo bilgilerini tek ekrandan yönetin.</p></div></div>
    {bulkNotice && <div className="notice order-bulk-notice" role="status">{bulkNotice}<button type="button" aria-label="Bildirimi kapat" onClick={() => setBulkNotice('')}>×</button></div>}
    <div className="order-tabs" role="tablist" aria-label="Sipariş durumları">{statuses.map(([value,label]) => <button type="button" role="tab" aria-selected={filters.status === value} className={filters.status === value ? 'active' : ''} key={value} onClick={() => selectStatus(value)}><span>{label}</span><b>{value === 'ALL' ? all.length : all.filter(x => x.derivedStatus.toUpperCase() === value).length}</b></button>)}</div>
    <section className="order-filter-panel" aria-label="Sipariş filtreleri"><div className="order-filter-primary"><div className="bulk-menu-shell"><button type="button" className="bulk-action" disabled={!selectedIds.length} aria-expanded={bulkOpen} onClick={() => setBulkOpen(value => !value)}>Toplu işlemler⌄</button>{bulkOpen && <div className="bulk-action-menu" role="menu"><button type="button" role="menuitem" onClick={() => void bulkAction('processing')}><b>01</b><span>İşleme Al<small>Yalnız yeni siparişler</small></span></button><button type="button" role="menuitem" onClick={() => void bulkAction('courier')}><b>02</b><span>Kargo Firmasını Değiştir<small>Seçili paketler</small></span></button><button type="button" role="menuitem" onClick={() => void bulkAction('invoice')}><b>03</b><span>Toplu Fatura Kes<small>Önce taslakları kontrol edin</small></span></button><button type="button" role="menuitem" onClick={() => void bulkAction('labels')}><b>04</b><span>Kargo Stickerlarını Yazdır<small>Takip numarası olanlar</small></span></button></div>}</div><label className="order-search"><span aria-hidden="true">⌕</span><input aria-label="Sipariş ara" value={filterForm.search} onChange={event => updateFilter('search', event.target.value)} placeholder="Sipariş no, paket no, takip no, alıcı, stok/model kodu veya barkod ara…" onKeyDown={event => { if (event.key === 'Enter') applyFilters() }} /></label><label>Platform<select value={filterForm.platform} onChange={event => updateFilter('platform', event.target.value)}><option value="ALL">Tüm platformlar</option>{platforms.map(value => <option key={value} value={value}>{value === 'TRENDYOL' ? 'Trendyol' : value}</option>)}</select></label><label>Sipariş durumu<select value={filterForm.status} onChange={event => updateFilter('status', event.target.value)}>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><button type="button" className="filter-toggle" onClick={() => setAdvancedFilters(value => !value)} aria-expanded={advancedFilters}>Gelişmiş Filtreler {advancedFilters ? '⌃' : '⌄'}</button><button type="button" className="secondary filter-clear" onClick={clearFilters}>Temizle</button><button type="button" className="filter-apply" onClick={applyFilters}>Uygula</button></div>{advancedFilters && <div className="order-filter-advanced"><label>Listeleme durumu<select value={filterForm.listing} onChange={event => updateFilter('listing', event.target.value)}><option value="ALL">Tüm kayıtlar</option><option value="OPEN">Açık siparişler</option><option value="CLOSED">Kapanan siparişler</option></select></label><label>Sipariş tarihi başlangıç<input type="date" value={filterForm.dateFrom} onChange={event => updateFilter('dateFrom', event.target.value)} /></label><label>Sipariş tarihi bitiş<input type="date" value={filterForm.dateTo} onChange={event => updateFilter('dateTo', event.target.value)} /></label><label>Kargo<select value={filterForm.cargo} onChange={event => updateFilter('cargo', event.target.value)}><option value="ALL">Tüm kargolar</option>{cargos.map(value => <option key={value}>{value}</option>)}</select></label><label>Fatura<select value={filterForm.invoice} onChange={event => updateFilter('invoice', event.target.value)}><option value="ALL">Tüm durumlar</option><option value="FATURA_BEKLIYOR">Fatura bekliyor</option><option value="FATURA_KESILDI">Fatura kesildi</option><option value="FATURA_REDDEDILDI">Fatura reddedildi</option></select></label><label>Sayfada<select value={pageSize} onChange={event => { setPageSize(Number(event.target.value)); setPage(1) }}>{[10, 20, 50, 100, 150].map(value => <option key={value} value={value}>{value} sipariş</option>)}</select></label></div>}</section>
    {query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : !all.length ? <Empty>Aktif ve kanıtlanmış bağlantıdan sipariş eşitlemesi çalıştırıldığında kayıtlar burada görünür.</Empty> : !items.length ? <Empty>Seçili durum ve filtrelerle eşleşen sipariş yok.</Empty> : <><div className="order-reference-table"><div className="order-reference-head"><label className="order-select"><input type="checkbox" checked={allPageSelected} onChange={event => togglePageSelection(event.target.checked)} aria-label="Sayfadaki siparişleri seç" /></label><strong>Sipariş Bilgileri</strong><strong>Alıcı</strong><strong>Bilgiler</strong><strong>Birim Fiyat</strong><strong>Kargo</strong><strong>Fatura</strong><strong>Durum</strong></div>{pageItems.map(item => <OrderReferenceRow item={item} key={item.id} selected={selectedIds.includes(item.id)} onSelect={checked => updateSelection(item.id, checked)} openMenu={menu?.orderId === item.id ? menu.kind : null} onMenuChange={kind => setMenu(kind ? { orderId: item.id, kind } : null)} onInvoiceCreate={() => { setMenu(null); setInvoiceDraftOrder(item) }} onInvoiceDetails={() => { setMenu(null); setInvoiceInfoOrder(item) }} onInvoiceUpload={() => { setMenu(null); setInvoiceUploadOrder(item) }} onCourierChange={() => { setMenu(null); setCourierOrder(item) }} />)}</div><div className="order-pagination"><span>{items.length} siparişten {(safePage - 1) * pageSize + 1}–{Math.min(safePage * pageSize, items.length)} arası gösteriliyor</span><div><button type="button" disabled={safePage <= 1} onClick={() => setPage(safePage - 1)}>‹ Önceki</button><b>{safePage} / {totalPages}</b><button type="button" disabled={safePage >= totalPages} onClick={() => setPage(safePage + 1)}>Sonraki ›</button></div></div></>}
    {invoiceInfoOrder && <InvoiceInfoModal item={invoiceInfoOrder} onClose={() => setInvoiceInfoOrder(null)} />}{invoiceViewerOrder && <InvoiceViewerModal item={invoiceViewerOrder} onClose={() => setInvoiceViewerOrder(null)} />}{invoiceDraftOrder && <InvoiceDraftModal item={invoiceDraftOrder} provider={provider} onClose={() => setInvoiceDraftOrder(null)} />}{invoiceUploadOrder && <InvoiceUploadModal item={invoiceUploadOrder} provider={provider} onClose={() => setInvoiceUploadOrder(null)} />}{courierOrder && <CourierChangeModal item={courierOrder} onClose={() => setCourierOrder(null)} />}
  </section>
}

export function ShipmentsPage() { const query = useQuery({ queryKey: ['shipments'], queryFn: () => hubApi<Page<Shipment>>('/shipments') }); return <ListPage eyebrow="Operasyon" title="Gönderiler" description="Paket durumu geriye alınmaz; desteklenmeyen aksiyon ve etiket biçimleri gösterilmez.">{query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : !query.data?.items.length ? <Empty>Order ingestion sonrasında shipment package kayıtları burada görünür.</Empty> : <div className="data-table" role="table">{query.data.items.map(item => <Link role="row" to={`/shipments/${item.id}`} key={item.id}><span><strong>{item.orderNumber}</strong><small>Paket {item.externalPackageId}</small></span><Badge value={item.status} /><span>{item.cargoTrackingNumber ?? '—'}</span><span><DateText value={item.statusOccurredAt} /></span></Link>)}</div>}</ListPage> }

export function ShipmentDetailPage() {
  const { id = '' } = useParams(); const client = useQueryClient(); const [notice, setNotice] = useState(''); const query = useQuery({ queryKey: ['shipment', id], queryFn: () => hubApi<ShipmentDetail>(`/shipments/${id}`) })
  async function action(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!query.data) return; const data = new FormData(event.currentTarget); try { JSON.parse(String(data.get('payloadJson') || '{}')); await hubApi(`/shipments/${id}/actions`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${query.data.package.version}"` }, body: JSON.stringify({ action: data.get('action'), payloadJson: data.get('payloadJson') }) }); setNotice('Paket aksiyonu kuyruğa alındı; sonuç read-back ile doğrulanacak.'); await client.invalidateQueries({ queryKey: ['shipment', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Aksiyon başlatılamadı.') } }
  async function label(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!query.data) return; const data = new FormData(event.currentTarget); try { await hubApi(`/shipments/${id}/common-label-jobs`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${query.data.package.version}"` }, body: JSON.stringify({ boxQuantity: Number(data.get('boxQuantity')), volumetricHeight: Number(data.get('volumetricHeight')) }) }); setNotice('Ortak etiket işi kuyruğa alındı.'); await client.invalidateQueries({ queryKey: ['shipment', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Etiket işi başlatılamadı.') } }
  async function labelProbe(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!query.data) return; const data = new FormData(event.currentTarget); try { await hubApi(`/shipments/${id}/label-capability-probes`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${query.data.package.version}"` }, body: JSON.stringify({ capabilityCode: data.get('capabilityCode'), boxQuantity: Number(data.get('boxQuantity')), volumetricHeight: Number(data.get('volumetricHeight')) }) }); setNotice('Stage etiket testi kuyruğa alındı; sonuç İşlem Takibi’nde görünür.'); await client.invalidateQueries({ queryKey: ['shipment', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Stage etiket testi başlatılamadı.') } }
  if (query.isLoading) return <section className="content"><Busy /></section>; if (query.isError || !query.data) return <section className="content"><ErrorBox error={query.error} /></section>; const item = query.data
  return <section className="content f3"><Link to="/shipments" className="back">← Gönderiler</Link><div className="page-heading"><div><p className="eyebrow">Gönderi detayı</p><h1>{item.package.orderNumber}</h1><p className="lede">Paket {item.package.externalPackageId}</p></div><Badge value={item.package.status} /></div>{notice && <div role="status" className="notice">{notice}</div>}<div className="split"><article className="panel"><h2>Paket</h2><dl className="details"><dt>Platform durumu</dt><dd>{item.package.rawStatus}</dd><dt>Takip numarası</dt><dd>{item.package.cargoTrackingNumber ?? '—'}</dd><dt>Güncelleme</dt><dd><DateText value={item.package.statusOccurredAt} /></dd></dl><h3>Belgeler</h3>{item.documents.length ? <ul className="plain-list">{item.documents.map(document => <li key={document.id}><strong>{document.documentKind} · {document.format}</strong><span>v{document.documentVersion} · {document.source}</span></li>)}</ul> : <p>Henüz belge yok.</p>}</article><article className="panel"><h2>Trendyol paket aksiyonu</h2>{item.allowedActions.length ? <form className="form-grid" onSubmit={action}><label>Aksiyon<select name="action">{item.allowedActions.map(value => <option key={value}>{value}</option>)}</select></label><label>Resmî aksiyon payload JSON<textarea name="payloadJson" defaultValue="{}" required /></label><button>Aksiyonu kuyruğa al</button></form> : <div className="unknown"><strong>Paket aksiyonu uygun değil</strong><p>Paket durumu veya production dış-yazma ayarları bu işlemi şu anda uygun kılmıyor.</p></div>}<h2>Ortak kargo etiketi</h2>{item.package.cargoTrackingNumber ? <>{item.supportedLabelFormats.length > 0 && <form className="inline-form" onSubmit={label}><label>Koli adedi<input name="boxQuantity" type="number" min="1" max="50" defaultValue="1" required /></label><label>Desi / hacim<input name="volumetricHeight" type="number" min="0" max="10000" step="0.01" defaultValue="1" required /></label><button>Etiket oluştur</button></form>}{item.isStageConnection && <details className="operation-details"><summary>Stage etiket testi</summary><form className="inline-form" onSubmit={labelProbe}><p>Yalnız test bağlantısındaki uygun pakette etiket okuma veya oluşturma sonucunu doğrular.</p><label>Test türü<select name="capabilityCode"><option value="LABEL_READ">Etiketi oku</option><option value="LABEL_WRITE">Etiket oluşturmayı dene</option></select></label><label>Koli adedi<input name="boxQuantity" type="number" min="1" max="50" defaultValue="1" required /></label><label>Desi / hacim<input name="volumetricHeight" type="number" min="0.01" max="10000" step="0.01" required /></label><button>Stage etiket testini çalıştır</button></form></details>}</> : <p>Etiket için takip numarası gerekir.</p>}</article></div></section>
}

function ReturnReferenceRow({ item, order }: { item: ReturnClaim; order: Order | null }) {
  const [previewImage, setPreviewImage] = useState<{ url: string; title: string } | null>(null)
  const navigate = useNavigate()
  const lines = order?.lines?.length ? order.lines : item.lines ?? []
  const shipment = order?.packages?.[0]
  const currency = order?.currency ?? item.currency
  const money = (value: number) => value.toLocaleString('tr-TR', { style: 'currency', currency })
  const total = order?.grossAmount || order?.netAmount || item.grossAmount || item.orderAmount
  const invoiceStatus = order?.invoiceStatus ?? item.invoiceStatus
  const discountAmount = order?.discountAmount ?? item.discountAmount
  const invoicedTotal = Math.max(0, total - discountAmount)
  const trackingNumber = shipment?.cargoTrackingNumber ?? order?.cargoTrackingNumber ?? item.cargoTrackingNumber
  const canTrack = Boolean(shipment?.id && trackingNumber && (shipment.status === 'SHIPPED' || shipment.status === 'IN_TRANSIT' || order?.derivedStatus === 'SHIPPED'))
  return <><Link to={`/returns/${item.id}`} className="return-reference-row" role="row">
    <span className="order-reference-meta"><strong>#{item.orderNumber}</strong><small>Sipariş tarihi: <DateText value={order?.orderedAt ?? item.orderedAt} /></small><small>Paket No: {shipment?.externalPackageId ?? item.packageNumber ?? '—'}</small><small>Teslimat No: {trackingNumber ?? '—'}</small></span>
    <span className="order-reference-buyer"><strong>{order?.customerName ?? item.customerName}</strong></span>
    <span className="order-reference-products return-order-products">{lines.length ? lines.map(line => { const imageUrl = line.imageUrl ?? order?.primaryImageUrl; return <article key={line.id}><span className="reference-product-media">{imageUrl ? <button type="button" className="product-image-button" onClick={event => { event.preventDefault(); event.stopPropagation(); setPreviewImage({ url: imageUrl, title: line.title }) }} aria-label={`${line.title} görselini büyüt`}><img src={imageUrl} alt={`${line.title} ürün görseli`} /></button> : <span className="reference-product-placeholder">↩</span>}<b className="quantity-bubble">{line.orderedQuantity}</b></span><div><strong>{line.title}</strong><small>Stok Kodu: {line.sku}</small>{optionRows(line.optionSignature).map(option => <small key={`${option.label}:${option.value}`}>{option.label}: {option.value}</small>)}<small>Barkod: {line.barcode ?? '—'}</small><small>Model Kodu: {line.modelCode ?? '—'}</small></div></article> }) : <div className="reference-no-product"><strong>{item.productCount} ürün</strong><small>Barkod: {item.primaryBarcode ?? '—'}</small></div>}</span>
    <span className="order-reference-prices">{lines.length ? lines.map(line => <strong key={line.id}>{money(line.unitPrice)}</strong>) : <strong>{money(item.orderAmount)}</strong>}</span>
    <span className="order-reference-cargo"><strong>{shipment?.cargoProviderName ?? order?.cargoProviderName ?? item.cargoProviderName ?? 'Kargo bilgisi yok'}</strong><b>{trackingNumber ?? '—'}</b>{canTrack && <button type="button" className="return-cargo-track" onClick={event => { event.preventDefault(); event.stopPropagation(); navigate(`/shipments/${shipment!.id}`) }}>Kargo takip →</button>}</span>
    <span className={`order-reference-invoice ${invoiceStatus === 'FATURA_BEKLIYOR' ? 'invoice-pending' : 'invoice-created'}`}><small>Satış tutarı</small><strong>{money(total)}</strong>{discountAmount > 0 && <small>Satıcı indirimi: {money(discountAmount)}</small>}<small>Faturalandırılmış tutar</small><strong>{money(invoicedTotal)}</strong><span>{invoiceStatus === 'FATURA_BEKLIYOR' ? 'Fatura bekleniyor' : invoiceStatus === 'FATURA_KONTROLDE' ? 'Fatura kontrol ediliyor' : invoiceStatus === 'FATURA_REDDEDILDI' ? 'Fatura reddedildi' : 'Fatura kesildi'}</span></span>
    <span><b>{item.reasonText ?? 'Belirtilmedi'}</b></span>
    <span><Badge value={item.status} />{item.actionDueAt && <small>{remainingText(item.actionDueAt)}</small>}<em>Detaylı bilgi gör →</em></span>
  </Link>{previewImage && <div className="workspace-modal-backdrop product-image-backdrop" role="presentation" onMouseDown={() => setPreviewImage(null)}><section className="workspace-modal product-image-modal" role="dialog" aria-modal="true" aria-label={`${previewImage.title} büyük ürün görseli`} onMouseDown={event => event.stopPropagation()}><header><h2>{previewImage.title}</h2><button type="button" className="modal-close" onClick={() => setPreviewImage(null)} aria-label="Pencereyi kapat">×</button></header><img src={previewImage.url} alt={`${previewImage.title} büyük ürün görseli`} /></section></div>}</>
}

export function ReturnsPage() {
  const [status, setStatus] = useState('ALL'); const [customer, setCustomer] = useState(''); const [orderNumber, setOrderNumber] = useState(''); const [claimCode, setClaimCode] = useState(''); const [barcode, setBarcode] = useState(''); const [reason, setReason] = useState(''); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [draft, setDraft] = useState(true)
  const client = useQueryClient(); const [notice, setNotice] = useState('')
  const query = useQuery({ queryKey: ['returns'], queryFn: () => hubApi<Page<ReturnClaim>>('/returns?limit=200') })
  const orders = useQuery({ queryKey: ['orders', 'returns-reference'], queryFn: loadAllOrders })
  const connections = useQuery({ queryKey: ['connections', 'returns'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const trendyolConnection = connections.data?.items.find(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE')
  const sync = useMutation({ mutationFn: () => { if (!trendyolConnection) throw new Error('Aktif Trendyol bağlantısı bulunamadı.'); return hubApi(`/connections/${trendyolConnection.id}/return-sync-jobs`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() } }) }, onSuccess: async () => { setNotice('İade eşitlemesi kuyruğa alındı. İş tamamlandığında kayıtlar otomatik yenilenir.'); await client.invalidateQueries({ queryKey: ['returns'] }) }, onError: value => setNotice(value instanceof Error ? value.message : 'İade eşitlemesi başlatılamadı.') })
  const items = query.data?.items ?? []
  const tabs = [['ALL', 'Tüm İadeler'], ['REQUESTED', 'Talep Oluşturulan'], ['SHIPPING', 'Kargoya Verilen'], ['ACTION_REQUIRED', 'Aksiyon Bekleyen'], ['APPROVED', 'Onaylanan'], ['REJECTED', 'Reddedilen'], ['REVIEW', 'Analiz'], ['DISPUTED', 'İhtilaflı'], ['SUSPENDED', 'Askıda İadeler']] as const
  const norm = (value: string | null) => (value ?? '').toLocaleLowerCase('tr-TR')
  const reasons = Array.from(new Set(items.map(item => item.reasonText).filter((value): value is string => Boolean(value))))
  const ordersByNumber = new Map((orders.data?.items ?? []).map(order => [order.orderNumber, order]))
  const visible = items.filter(item => {
    const order = ordersByNumber.get(item.orderNumber)
    const date = item.orderedAt?.slice(0, 10) ?? ''
    return (status === 'ALL' || returnGroup(item.status) === status) && (!draft || (!customer || norm(order?.customerName ?? item.customerName).includes(norm(customer))) && (!orderNumber || item.orderNumber.includes(orderNumber)) && (!claimCode || norm(item.externalClaimId).includes(norm(claimCode))) && (!barcode || [item.primaryBarcode ?? '', ...(order?.lines ?? []).map(line => line.barcode ?? '')].some(value => norm(value).includes(norm(barcode)))) && (!reason || item.reasonText === reason) && (!from || date >= from) && (!to || date <= to))
  })
  function clearFilters() { setCustomer(''); setOrderNumber(''); setClaimCode(''); setBarcode(''); setReason(''); setFrom(''); setTo(''); setDraft(true) }
  return <section className="content f3 returns-page reference-returns-page">
    <div className="return-reference-tabs" role="tablist" aria-label="İade durumları">{tabs.map(([value, label]) => <button key={value} type="button" role="tab" aria-selected={status === value} className={status === value ? 'active' : ''} onClick={() => setStatus(value)}><strong>{label}</strong><small>{value === 'ALL' ? items.length : items.filter(item => returnGroup(item.status) === value).length} Paket</small></button>)}</div>
    <section className="return-reference-filters" aria-label="İade filtreleri"><input aria-label="Müşteri adı" placeholder="Müşteri Adı" value={customer} onChange={event => setCustomer(event.target.value)} /><input aria-label="Sipariş no" placeholder="Sipariş No" value={orderNumber} onChange={event => setOrderNumber(event.target.value)} /><input aria-label="İade kodu" placeholder="İade Kodu" value={claimCode} onChange={event => setClaimCode(event.target.value)} /><input aria-label="Barkod" placeholder="Barkod" value={barcode} onChange={event => setBarcode(event.target.value)} /><select aria-label="İade sebebi" value={reason} onChange={event => setReason(event.target.value)}><option value="">İade Sebebi</option>{reasons.map(value => <option key={value}>{value}</option>)}</select><input aria-label="İade talep başlangıç tarihi" type="date" value={from} onChange={event => setFrom(event.target.value)} /><input aria-label="İade talep bitiş tarihi" type="date" value={to} onChange={event => setTo(event.target.value)} /><div className="return-filter-actions"><button type="button" className="secondary" onClick={clearFilters}>Temizle</button><button type="button" onClick={() => setDraft(true)}>Filtrele</button></div></section>
    {notice && <div role="status" className="notice">{notice}</div>}
    <section className="return-reference-workspace"><header><div><h1>{tabs.find(tab => tab[0] === status)?.[1]}</h1><p>Filtreleme Sonuçları: Toplam {visible.length} iade bilgisi</p></div><button type="button" disabled={!trendyolConnection || sync.isPending} onClick={() => sync.mutate()}>{sync.isPending ? 'Eşitleniyor…' : 'İadeleri eşitle'}</button></header>{query.isLoading ? <Busy /> : query.isError ? <ErrorBox error={query.error} /> : !visible.length ? <Empty>{items.length ? 'Seçili filtreyle eşleşen iade yok.' : 'İadeleri eşitle düğmesiyle güncel talepleri çekin.'}</Empty> : <div className="return-reference-table" role="table"><div className="return-reference-head" role="row"><strong>Sipariş Bilgileri</strong><strong>Alıcı</strong><strong>Bilgiler</strong><strong>Birim Fiyat</strong><strong>Kargo</strong><strong>Fatura</strong><strong>İade Sebebi</strong><strong>Durum</strong></div>{visible.map(item => <ReturnReferenceRow key={item.id} item={item} order={ordersByNumber.get(item.orderNumber) ?? null} />)}</div>}</section>
  </section>
}

export function ReturnDetailPage() {
  const { id = '' } = useParams(); const client = useQueryClient(); const [notice, setNotice] = useState(''); const [evidenceAssetIds, setEvidenceAssetIds] = useState<string[]>([]); const [action, setAction] = useState('APPROVE'); const [reasonId, setReasonId] = useState('')
  const query = useQuery({ queryKey: ['return', id], queryFn: () => hubApi<ReturnDetail>(`/returns/${id}`) })
  const reasons = useQuery({ queryKey: ['return-reasons', id], queryFn: () => hubApi<ReturnIssueReason[]>(`/returns/${id}/rejection-reasons`), enabled: query.data?.allowedActions.includes('REJECT') === true, retry: false })
  const selectedReason = reasons.data?.find(x => x.id === reasonId)
  async function uploadFile(file: File) { if (!file.size) return; const body = new FormData(); body.set('file', file); try { const asset = await hubApi<{ id: string }>('/files/return-evidence', { method: 'POST', body }); setEvidenceAssetIds(ids => ids.includes(asset.id) ? ids : [...ids, asset.id]); setNotice('Kanıt güvenli özel depoya yüklendi.') } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Kanıt yüklenemedi.') } }
  async function decide(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!query.data) return; const data = new FormData(event.currentTarget); try { await hubApi(`/returns/${id}/actions`, { method: 'POST', headers: { 'Idempotency-Key': idempotency(), 'If-Match': `"v${query.data.version}"` }, body: JSON.stringify({ action, reasonCode: action === 'REJECT' ? reasonId : null, explanation: action === 'REJECT' ? data.get('explanation') : null, evidenceAssetIds }) }); setNotice('İade kararı kuyruğa alındı; uzak sonuç eşitlemeyle doğrulanacak.'); await client.invalidateQueries({ queryKey: ['return', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'İade kararı başlatılamadı.') } }
  async function disposition(event: FormEvent<HTMLFormElement>, line: ReturnLine) { event.preventDefault(); const data = new FormData(event.currentTarget); try { await hubApi(`/returns/${id}/stock-dispositions`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify({ returnLineId: line.id, disposition: data.get('disposition'), quantity: Number(data.get('quantity')), reason: data.get('reason') }) }); setNotice('İade stok kararı kaydedildi. Yalnız Satılabilir seçimi eldeki stoğu artırır.'); await client.invalidateQueries({ queryKey: ['return', id] }) } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Stok kararı kaydedilemedi.') } }
  if (query.isLoading) return <section className="content"><Busy /></section>; if (query.isError || !query.data) return <section className="content"><ErrorBox error={query.error} /></section>; const item = query.data; const lines = item.lines ?? []
  return <section className="content f3 return-detail-page"><Link to="/returns" className="back">← İadeler</Link><div className="page-heading"><div><p className="eyebrow">İade detayı · Claim {item.externalClaimId}</p><h1>{item.orderNumber}</h1><p className="lede">{item.customerName} · {item.orderAmount.toLocaleString('tr-TR', { style: 'currency', currency: item.currency })}</p></div><Badge value={item.status} /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="detail-grid"><article className="panel"><h2>Talep ve süre</h2><dl className="details"><dt>Platform durumu</dt><dd>{item.rawStatus}</dd><dt>Neden</dt><dd>{item.reasonText ?? 'Belirtilmedi'}</dd><dt>Sipariş tarihi</dt><dd><DateText value={item.orderedAt} /></dd><dt>Otomatik işlem</dt><dd className={item.actionDueAt && new Date(item.actionDueAt).getTime() - Date.now() < 86_400_000 ? 'deadline critical' : ''}>{remainingText(item.actionDueAt)}</dd><dt>Kargo</dt><dd>{item.cargoProviderName ?? '—'} · {item.cargoTrackingNumber ?? '—'}</dd></dl></article><article className="panel"><h2>Onay / ret</h2>{item.allowedActions.length ? <form className="form-grid" onSubmit={decide}><label>Karar<select name="action" value={action} onChange={event => setAction(event.target.value)}>{item.allowedActions.filter(value => value === 'APPROVE' || value === 'REJECT').map(value => <option key={value}>{value}</option>)}</select></label>{action === 'REJECT' && <><label>Trendyol ret nedeni<select value={reasonId} onChange={event => setReasonId(event.target.value)} required><option value="">Seçin</option>{reasons.data?.map(reason => <option key={reason.id} value={reason.id}>{reason.name}</option>)}</select></label><label>Açıklama<textarea name="explanation" maxLength={500} required /></label><label>Kanıt (PDF/JPEG/PNG, en fazla 10 MiB)<input name="file" type="file" accept="application/pdf,image/jpeg,image/png" onChange={event => { const file = event.currentTarget.files?.[0]; if (file) void uploadFile(file) }} /></label><small>{evidenceAssetIds.length} kanıt hazır{selectedReason?.evidenceRequired ? ' · bu neden için zorunlu' : ''}</small></>}<button disabled={action === 'REJECT' && (!reasonId || (selectedReason?.evidenceRequired && !evidenceAssetIds.length))}>Kararı kuyruğa al</button></form> : <div className="unknown"><strong>İade aksiyonu uygun değil</strong><p>Sağlayıcının mevcut iade durumu bu kayıtta henüz onay veya ret işlemini desteklemiyor.</p></div>}</article></div>
    <div className="panel"><h2>İade paketi ürünleri ve stok kabulü</h2><p className="notice"><strong>Stok otomatik artmaz.</strong> Ürün fiziksel olarak kontrol edildikten sonra “Satılabilir” seçilirse stok artar; Karantina, Hasarlı ve Teslim Alınmadı seçimleri stoğu artırmaz.</p>{!lines.length ? <Empty>İade satırı bulunamadı.</Empty> : <div className="return-line-list">{lines.map(line => <article className="return-line" key={line.id}>{line.imageUrl ? <img className="operation-image" src={line.imageUrl} alt="" /> : <span className="operation-image placeholder">▧</span>}<span><strong>{line.title}</strong><small>{line.sku}{line.barcode ? ` · ${line.barcode}` : ''}</small><small>{line.quantity} adet · kalan karar {line.remainingQuantity}</small></span>{item.stockDispositionAvailable && line.remainingQuantity > 0 ? <form className="stock-disposition" onSubmit={event => disposition(event, line)}><select name="disposition" aria-label="Stok kabul kararı"><option value="PASS">Satılabilir — stoğa ekle</option><option value="QUARANTINE">Karantina — stoğa ekleme</option><option value="DAMAGED">Hasarlı — stoğa ekleme</option><option value="NOT_RECEIVED">Teslim alınmadı</option></select><input name="quantity" type="number" min="0.01" max={line.remainingQuantity} step="0.01" defaultValue={line.remainingQuantity} required /><input name="reason" placeholder="Kontrol notu" required /><button>Kararı kaydet</button></form> : <Badge value={line.remainingQuantity === 0 ? 'TAMAMLANDI' : line.hasInventoryMapping ? 'ONAY_BEKLIYOR' : 'STOK_ESLEME_GEREKLI'} />}</article>)}</div>}</div>
  </section>
}

export function MappingPage({ kind }: { kind: 'categories' | 'attributes' }) {
  if (kind === 'attributes') return <LegacyMappingPage kind="attributes" />
  return new URLSearchParams(window.location.search).get('view') === 'brands' ? <BrandMappingPage /> : <CategoryMappingWorkspace />
}

function CategoryMappingWorkspace() {
  const client = useQueryClient()
  const [connectionId, setConnectionId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState(''); const [categoryName, setCategoryName] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const localCategories = useQuery({ queryKey: ['categories', 'mapping'], queryFn: () => hubApi<Page<LocalCategory>>('/catalog/categories?limit=200') })
  const currentCategory = useQuery({ queryKey: ['category', localId, 'mapping'], queryFn: () => hubApi<LocalCategory>(`/catalog/categories/${localId}`), enabled: !!localId })
  const localAttributes = useQuery({ queryKey: ['attributes', 'mapping-builder'], queryFn: () => hubApi<Page<LocalAttribute>>('/catalog/attributes?limit=200') })
  const requirements = useQuery({ queryKey: ['category-requirements', localId, 'mapping'], queryFn: () => hubApi<CategoryRequirementView[]>(`/catalog/categories/${localId}/attribute-requirements`), enabled: !!localId, retry: false })
  const references = useQuery({ queryKey: ['reference-categories', connectionId], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId, retry: false })
  const mapping = useQuery({ queryKey: ['category-mapping', localId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/categories/${localId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!localId && !!connectionId, retry: false })
  const save = useMutation({ mutationFn: () => { if (!references.data || !localId || !externalId) throw new Error('Panel kategorisi ve Trendyol kategorisi zorunludur.'); return hubApi<CatalogMapping>(`/mappings/categories/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) }) }, onSuccess: async value => { setNotice('Kategori eşleşti. 3. adımda özellik eşlemelerine devam edebilirsiniz.'); setExternalId(value.externalId); client.setQueryData(['category-mapping', localId, connectionId], value); client.setQueryData(['category-mapping', localId, connectionId, 'embedded'], value); client.setQueryData<CatalogMapping[]>(['category-mappings', connectionId], current => current ? [...current.filter(item => item.localId !== value.localId), value] : [value]); await Promise.all([client.invalidateQueries({ queryKey: ['category-mapping', localId, connectionId] }), client.invalidateQueries({ queryKey: ['category-mapping', localId, connectionId, 'embedded'] }), client.invalidateQueries({ queryKey: ['category-mappings', connectionId] })]) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Eşleme kaydedilemedi.') })
  const createCategory = useMutation({ mutationFn: () => { if (!categoryName.trim()) throw new Error('Kategori adı zorunludur.'); return hubApi<LocalCategory>('/catalog/categories', { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify({ name: categoryName.trim(), parentId: null }) }) }, onSuccess: async category => { client.setQueryData<Page<LocalCategory>>(['categories', 'mapping'], current => current ? { ...current, items: [...current.items.filter(item => item.id !== category.id), category] } : current); setLocalId(category.id); setExternalId(''); setCategoryName(''); setNotice(`“${category.name}” panel kategorisi oluşturuldu ve seçildi.`); await client.invalidateQueries({ queryKey: ['categories', 'mapping'] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Kategori oluşturulamadı.') })
  useEffect(() => { setExternalId(mapping.data?.externalId ?? '') }, [mapping.data])
  const trendyolConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []
  useEffect(() => { if (!connectionId && trendyolConnections.length) setConnectionId(trendyolConnections[0].id) }, [connectionId, trendyolConnections])
  const activeCategories = localCategories.data?.items.filter(item => item.isActive) ?? []
  const localLeaves = activeCategories.filter(item => item.isLeaf)
  const externalLeaves = references.data?.items.filter(item => item.isActive && item.isLeaf) ?? []
  const localOptions = localLeaves.map(item => ({ value: item.id, label: item.path, description: `Panel kategorisi · Seviye ${item.depth + 1}` }))
  const externalOptions = externalLeaves.map(item => ({ value: item.externalId, label: cleanTrendyolCategoryPath(item.path), description: `Trendyol kategori no: ${item.externalId}` }))
  const archiveCategory = useMutation({ mutationFn: (category: LocalCategory) => hubApi<LocalCategory>(`/catalog/categories/${category.id}`, { method: 'PATCH', headers: { 'If-Match': `"v${category.version}"` }, body: JSON.stringify({ name: category.name, parentId: null, isActive: false }) }), onSuccess: async (_, category) => { if (localId === category.id) { setLocalId(''); setExternalId('') }; await client.invalidateQueries({ queryKey: ['categories', 'mapping'] }); setNotice(`“${category.name}” panel kategorilerinden kaldırıldı.`) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Kategori kaldırılamadı.') })
  return <section className="content f3 mapping-page mapping-workspace"><div className="mapping-workspace-heading"><div><p className="eyebrow">Merkezi katalog sistemi</p><h1>Eşleştirme Merkezi</h1></div></div><MappingViewTabs active="category" />{notice && <div role="status" className="notice">{notice}</div>}
    <article className="panel mapping-console">
      <form className="platform-category-create" onSubmit={event => { event.preventDefault(); createCategory.mutate() }}><label>Yeni panel kategorisi<input aria-label="Yeni panel kategorisi adı" maxLength={160} value={categoryName} onChange={event => setCategoryName(event.target.value)} placeholder="Örn. Anne Bluz" required /></label><button disabled={createCategory.isPending}>{createCategory.isPending ? 'Ekleniyor…' : '+ Kategori ekle'}</button></form><div className="category-chip-list" aria-label="Eklenen panel kategorileri">{activeCategories.length ? activeCategories.map(category => <span key={category.id} className={category.id === localId ? 'active' : ''}><button type="button" onClick={() => { setLocalId(category.id); setExternalId(''); setNotice('') }}>{category.name}</button><button type="button" className="category-chip-remove" aria-label={`${category.name} kategorisini kaldır`} onClick={() => archiveCategory.mutate(category)} disabled={archiveCategory.isPending}>×</button></span>) : <small>Henüz panel kategorisi eklenmedi.</small>}</div>
      <div className="mapping-pair-grid"><section className="mapping-side local"><div className="mapping-side-head"><span>Panel kataloğu</span><strong>Panel kategorisi</strong><small>Eklediğiniz panel kategorilerinden birini seçin.</small></div><SearchableSelect label="Panel kategorisi" value={localId} options={localOptions} placeholder="Kategori adında ara" disabled={!connectionId} onChange={value => { setLocalId(value); setExternalId(''); setNotice('') }} /></section><div className="mapping-link-rail" aria-hidden="true"><span>⇄</span><small>Eşleştir</small></div><section className="mapping-side remote"><div className="mapping-side-head"><span>Trendyol kataloğu</span><strong>Trendyol kategorisi</strong><small>Güncel referans listesindeki yaprak kategoriyi seçin.</small></div><SearchableSelect label="Trendyol yaprak kategorisi" value={externalId} options={externalOptions} placeholder={references.isLoading ? 'Kategoriler yükleniyor…' : 'Kategori adı, yol veya kategori no ara'} disabled={!localId || references.isLoading || references.isError} onChange={setExternalId} /></section></div>
      {connections.isError || localCategories.isError ? <ErrorBox error={connections.error ?? localCategories.error} /> : !trendyolConnections.length && !connections.isLoading ? <div className="mapping-action"><span>Aktif Trendyol bağlantısı gerekir.</span><Link className="button-link" to="/integrations">Platformlara git</Link></div> : references.isError ? <div className="unknown"><strong>Güncel kategori listesi yok</strong><p>Bağlantı ekranından “Kategorileri eşitle” işlemini çalıştırın.</p><Link className="button-link" to={`/integrations/${connectionId}`}>Bağlantıya git</Link></div> : connectionId && references.data ? <div className="mapping-action"><span><strong>{externalLeaves.length.toLocaleString('tr-TR')}</strong> yaprak kategori · {new Date(references.data.fetchedAt).toLocaleString('tr-TR')}{mapping.data ? ` · Kayıt v${mapping.data.version}` : ''}</span><button type="button" disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Eşleniyor…' : 'Eşle'}</button></div> : null}
    </article>
    <CategoryRequirementBuilder categoryId={localId} categoryVersion={currentCategory.data?.version ?? null} attributes={localAttributes.data?.items.filter(item => item.isActive) ?? []} requirements={requirements.data ?? []} onNotice={setNotice} onSaved={async () => { await client.invalidateQueries({ queryKey: ['category-requirements', localId, 'mapping'] }); await client.invalidateQueries({ queryKey: ['category', localId, 'mapping'] }); await client.invalidateQueries({ queryKey: ['attributes', 'mapping-builder'] }) }} />
    <CategoryAttributeWorkspace connectionId={connectionId} localCategoryId={localId} localCategories={localLeaves} localAttributes={localAttributes.data?.items.filter(item => item.isActive) ?? []} onNotice={setNotice} />
  </section>
}

function LegacyMappingPage({ kind }: { kind: 'categories' | 'attributes' }) {
  const client = useQueryClient(); const [platform, setPlatform] = useState('TRENDYOL'); const [connectionId, setConnectionId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState(''); const [localSearch, setLocalSearch] = useState(''); const [externalSearch, setExternalSearch] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const localCategories = useQuery({ queryKey: ['categories', 'mapping'], queryFn: () => hubApi<Page<LocalCategory>>('/catalog/categories?limit=200'), enabled: kind === 'categories' })
  const currentCategory = useQuery({ queryKey: ['category', localId, 'mapping'], queryFn: () => hubApi<LocalCategory>(`/catalog/categories/${localId}`), enabled: !!localId })
  const localAttributes = useQuery({ queryKey: ['attributes', 'mapping-builder'], queryFn: () => hubApi<Page<LocalAttribute>>('/catalog/attributes?limit=200') })
  const requirements = useQuery({ queryKey: ['category-requirements', localId, 'mapping'], queryFn: () => hubApi<CategoryRequirementView[]>(`/catalog/categories/${localId}/attribute-requirements`), enabled: !!localId, retry: false })
  const references = useQuery({ queryKey: ['reference-categories', connectionId], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories?connectionId=${encodeURIComponent(connectionId)}`), enabled: kind === 'categories' && !!connectionId && platform === 'TRENDYOL', retry: false })
  const mapping = useQuery({ queryKey: ['category-mapping', localId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/categories/${localId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: kind === 'categories' && !!localId && !!connectionId && platform === 'TRENDYOL', retry: false })
  const save = useMutation({ mutationFn: () => {
    if (!references.data || !localId || !externalId) throw new Error('Bağlantı, panel kategorisi ve Trendyol kategorisi zorunludur.')
    return hubApi<CatalogMapping>(`/mappings/categories/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) })
  }, onSuccess: async value => { setNotice('Kategori eşlemesi doğrulandı ve kaydedildi.'); setExternalId(value.externalId); await client.invalidateQueries({ queryKey: ['category-mapping', localId, connectionId] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Eşleme kaydedilemedi.') })
  useEffect(() => { if (mapping.data) setExternalId(mapping.data.externalId) }, [mapping.data])
  const trendyolConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []
  const localLeaves = localCategories.data?.items.filter(item => item.isActive && item.isLeaf) ?? []
  const externalLeaves = references.data?.items.filter(item => item.isActive && item.isLeaf) ?? []
  const filteredLocalLeaves = localLeaves.filter(item => !localSearch.trim() || item.path.toLocaleLowerCase('tr-TR').includes(localSearch.trim().toLocaleLowerCase('tr-TR')))
  const filteredExternalLeaves = externalLeaves.filter(item => !externalSearch.trim() || cleanTrendyolCategoryPath(item.path).toLocaleLowerCase('tr-TR').includes(externalSearch.trim().toLocaleLowerCase('tr-TR')))

  if (kind === 'categories' && new URLSearchParams(window.location.search).get('view') === 'brands') return <BrandMappingPage />
  if (kind === 'attributes') return <AttributeMappingPage />

  return <section className="content f3 mapping-page"><div className="page-heading"><div><p className="eyebrow">Merkezi katalog sistemi</p><h1>Kategori &amp; özellik eşlemeleri</h1><p className="lede">Panel kategorisini seçili pazaryerinin kategorisiyle eşleştirin; ardından kategori özellik başlıkları ve değer eşleştirmelerini aynı akışta tamamlayın.</p></div><Badge value="SAFE READ" /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <article className="panel mapping-step"><div className="editor-section-title"><span>1</span><div><h2>Panel kategorisini pazaryeri ile eşle</h2><p>Her pazaryeri için ayrı kategori eşleşmesi yapabilirsiniz.</p></div></div><div className="platform-choice"><strong>Pazaryeri:</strong>{['TRENDYOL', 'HEPSIBURADA', 'PAZARAMA', 'N11', 'SHOPIFY'].map(code => <button type="button" key={code} className={platform === code ? 'active' : ''} onClick={() => { setPlatform(code); setNotice('') }}>{code === 'TRENDYOL' ? 'Trendyol' : code === 'HEPSIBURADA' ? 'Hepsiburada' : code === 'PAZARAMA' ? 'Pazarama' : code}</button>)}</div>{platform !== 'TRENDYOL' ? <div className="unknown"><strong>Bu tasarım hazır</strong><p>Aktif fonksiyonel eşleme bu sürümde Trendyol için çalışır; diğer platform sekmeleri arayüz uyumunu korumak için gösterilir.</p></div> : <><div className="mapping-fields"><label>Aktif Trendyol bağlantısı<select aria-label="Aktif Trendyol bağlantısı" value={connectionId} onChange={event => { setConnectionId(event.target.value); setLocalId(''); setExternalId(''); setNotice('') }}><option value="">Bağlantı seçin</option>{trendyolConnections.map(item => <option value={item.id} key={item.id}>{item.displayName} · {item.externalStoreId}</option>)}</select></label><label>Panel yaprak kategorisi<input aria-label="Panel kategorilerinde ara" value={localSearch} onChange={event => setLocalSearch(event.target.value)} placeholder="Panel kategorilerinde ara" disabled={!connectionId} /><select aria-label="Panel yaprak kategorisi" value={localId} onChange={event => { setLocalId(event.target.value); setExternalId(''); setNotice('') }} disabled={!connectionId}><option value="">Kategori seçin</option>{filteredLocalLeaves.map(item => <option value={item.id} key={item.id}>{item.path}</option>)}</select></label><label>Trendyol yaprak kategorisi<input aria-label="Trendyol kategorilerinde ara" value={externalSearch} onChange={event => setExternalSearch(event.target.value)} placeholder="Trendyol kategorilerinde ara" disabled={!localId} /><select aria-label="Trendyol yaprak kategorisi" value={externalId} onChange={event => setExternalId(event.target.value)} disabled={!localId || references.isLoading || references.isError}><option value="">Kategori seçin</option>{filteredExternalLeaves.map(item => <option value={item.externalId} key={item.externalId}>{cleanTrendyolCategoryPath(item.path)}</option>)}</select></label></div>{connections.isError || localCategories.isError ? <ErrorBox error={connections.error ?? localCategories.error} /> : !trendyolConnections.length && !connections.isLoading ? <div className="mapping-action"><span>REFERENCE_READ kanıtlı ACTIVE Trendyol bağlantısı gerekir.</span><Link className="button-link" to="/integrations">Platformlara git</Link></div> : references.isError ? <div className="unknown"><strong>Güncel kategori snapshot’ı yok</strong><p>Bağlantı ekranından “Kategorileri eşitle” işlemini çalıştırın.</p><Link className="button-link" to={`/integrations/${connectionId}`}>Bağlantıya git</Link></div> : references.isLoading ? <Busy text="Kategori snapshot’ı yükleniyor…" /> : connectionId && references.data ? <div className="mapping-action"><span>{externalLeaves.length.toLocaleString('tr-TR')} yaprak kategori · snapshot {new Date(references.data.fetchedAt).toLocaleString('tr-TR')}{mapping.data ? ` · mevcut eşleme v${mapping.data.version}` : ''}</span><button type="button" disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Kaydediliyor…' : mapping.data ? 'Eşlemeyi güncelle' : 'Eşlemeyi doğrula ve kaydet'}</button></div> : null}</>}</article>

    <CategoryRequirementBuilder categoryId={localId} categoryVersion={currentCategory.data?.version ?? null} attributes={localAttributes.data?.items.filter(item => item.isActive) ?? []} requirements={requirements.data ?? []} onNotice={setNotice} onSaved={async () => { await client.invalidateQueries({ queryKey: ['category-requirements', localId, 'mapping'] }); await client.invalidateQueries({ queryKey: ['category', localId, 'mapping'] }); await client.invalidateQueries({ queryKey: ['attributes', 'mapping-builder'] }) }} />

    <CategoryAttributeWorkspace connectionId={connectionId} localCategoryId={localId} localCategories={localLeaves} localAttributes={localAttributes.data?.items.filter(item => item.isActive) ?? []} onNotice={setNotice} />
  </section>
}

function slug(value: string) { return value.toLocaleLowerCase('tr-TR').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || `attr-${Date.now()}` }

function cleanTrendyolCategoryPath(value: string) {
  return value.replace(/\[TDG\]\s*/gi, '').replace(/\(\s*TDG\s*\)\s*/gi, '').replace(/\s*\/\s*/g, ' / ').trim()
}

function CategoryRequirementBuilder({ categoryId, categoryVersion, attributes, requirements, onNotice, onSaved }: { categoryId: string; categoryVersion: number | null; attributes: LocalAttribute[]; requirements: CategoryRequirementView[]; onNotice: (value: string) => void; onSaved: () => Promise<void> }) {
  const client = useQueryClient()
  const [selectedAttributeId, setSelectedAttributeId] = useState(''); const [title, setTitle] = useState(''); const [values, setValues] = useState(''); const [feedback, setFeedback] = useState(''); const [removingRequirementId, setRemovingRequirementId] = useState('')
  function updateAttributeCache(attribute: LocalAttribute) {
    client.setQueryData<Page<LocalAttribute>>(['attributes', 'mapping-builder'], current => current ? { ...current, items: [...current.items.filter(item => item.id !== attribute.id), attribute] } : current)
  }
  async function persist(next: Array<{ attributeId: string; isRequired: boolean; allowsCustomValue: boolean }>) {
    if (!categoryId || categoryVersion == null) return onNotice('Önce panel kategorisini seçin.')
    await hubApi(`/catalog/categories/${categoryId}/attribute-requirements`, { method: 'PUT', headers: { 'If-Match': `"v${categoryVersion}"` }, body: JSON.stringify(next.map((item, index) => ({ ...item, displayOrder: index }))) })
    await onSaved()
  }
  const current = requirements.map(item => ({ attributeId: item.attributeId, isRequired: item.isRequired, allowsCustomValue: item.allowsCustomValue }))
  const visibleRequirements = categoryId ? requirements : attributes.map(attribute => ({ attributeId: attribute.id, isRequired: false, allowsCustomValue: !attribute.values.length, displayOrder: 0, attribute }))
  async function addAttribute(mode: 'create' | 'values') {
    try {
      if (mode === 'values') {
        if (!selectedAttributeId) return setFeedback('Önce değer eklemek istediğiniz özellik kartını seçin.')
        const requestedValues = values.split(',').map(item => item.trim()).filter(Boolean)
        if (!requestedValues.length) return setFeedback('Eklenecek seçenek değerlerini virgülle girin.')
        const updatedAttribute = await hubApi<LocalAttribute>(`/catalog/attributes/${selectedAttributeId}/values`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify(requestedValues.map((value, sortOrder) => ({ value, sortOrder }))) })
        updateAttributeCache(updatedAttribute)
        setValues(''); setFeedback('Yeni seçenek değerleri eklendi.'); await onSaved(); return
      }
      if (!title.trim()) return onNotice('Yeni özellik başlığı girin.')
      let createdAttribute: LocalAttribute | null = null
      {
        const selectableValues = values.split(',').map(item => item.trim()).filter(Boolean)
        const payload = { code: slug(title), name: title.trim(), dataType: selectableValues.length ? 'SINGLE_SELECT' : 'TEXT', selectionMode: selectableValues.length ? 'SINGLE' : null, unit: null, values: selectableValues.map((value, index) => ({ value, sortOrder: index })) }
        createdAttribute = await hubApi<LocalAttribute>('/catalog/attributes', { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify(payload) })
      }
      updateAttributeCache(createdAttribute)
      if (categoryId) await persist([...current, { attributeId: createdAttribute.id, isRequired: true, allowsCustomValue: !createdAttribute.values.length }])
      setSelectedAttributeId(createdAttribute.id); setTitle(''); setValues(''); setFeedback('Kategori özellik başlığı kaydedildi.')
    } catch (reason) { setFeedback(reason instanceof Error ? reason.message : 'Özellik kaydedilemedi.') }
  }
  async function removeValue(attributeId: string, valueId: string) {
    try {
      const updatedAttribute = await hubApi<LocalAttribute>(`/catalog/attributes/${attributeId}/values/${valueId}`, { method: 'DELETE' })
      updateAttributeCache(updatedAttribute)
      setFeedback('Seçenek değeri kaldırıldı.'); await onSaved()
    } catch (reason) { setFeedback(reason instanceof Error ? reason.message : 'Seçenek değeri kaldırılamadı.') }
  }
  async function removeAttribute(item: CategoryRequirementView) {
    try {
      setRemovingRequirementId(item.attributeId)
      await hubApi<LocalAttribute>(`/catalog/attributes/${item.attributeId}`, { method: 'DELETE', headers: { 'If-Match': `"v${item.attribute.version}"` } })
      client.setQueryData<Page<LocalAttribute>>(['attributes', 'mapping-builder'], current => current ? { ...current, items: current.items.filter(attribute => attribute.id !== item.attributeId) } : current)
      if (selectedAttributeId === item.attributeId) setSelectedAttributeId('')
      setFeedback(`${item.attribute.name} kaldırıldı.`)
      await onSaved()
    } catch (reason) { setFeedback(reason instanceof Error ? reason.message : 'Özellik başlığı kaldırılamadı.') }
    finally { setRemovingRequirementId('') }
  }
  return <article className="panel mapping-step"><div className="editor-section-title"><span>2</span><div><h2>Ürün özellikleri</h2><p>Ürün aktarımında kullanacağınız özellik başlıklarını ve seçilebilir seçeneklerini bir kez oluşturun.</p></div></div><div className="mapping-fields attribute-entry-fields"><label>Yeni özellik başlığı<input value={title} onChange={event => setTitle(event.target.value)} placeholder="Örn. Kol Boyu, Paça Türü, Materyal" /></label><button type="button" onClick={() => void addAttribute('create')}>+ Özellik ekle</button><label>Yeni seçenek değerleri<input value={values} onChange={event => setValues(event.target.value)} placeholder="Virgülle: Uzun kol, Kısa kol" /></label><button type="button" disabled={!selectedAttributeId || !values.trim()} onClick={() => void addAttribute('values')}>+ Seçili özelliğe değer ekle</button></div>{feedback && <p className="attribute-feedback" role="status">{feedback}</p>}<div className="attribute-builder-list">{visibleRequirements.length ? visibleRequirements.map(item => <article className={`attribute-summary-card selectable ${selectedAttributeId === item.attributeId ? 'selected' : ''}`} key={item.attributeId} role="button" tabIndex={0} aria-pressed={selectedAttributeId === item.attributeId} onClick={() => { setSelectedAttributeId(item.attributeId); setTitle(''); setFeedback('') }} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); setSelectedAttributeId(item.attributeId); setTitle(''); setFeedback('') } }}><div className="attribute-summary-title"><strong>{item.attribute.name}</strong><p>{item.attribute.values.length ? `${item.attribute.values.length} seçenek` : 'Serbest değer'}</p><button type="button" className="secondary" aria-label={`${item.attribute.name} başlığını kaldır`} disabled={removingRequirementId === item.attributeId} onClick={event => { event.stopPropagation(); void removeAttribute(item) }}>{removingRequirementId === item.attributeId ? 'Kaldırılıyor…' : 'Başlığı kaldır'}</button></div>{item.attribute.values.length > 0 && <div className="attribute-value-list">{item.attribute.values.filter(value => value.isActive).map(value => <span key={value.id}>{value.value}<button type="button" aria-label={`${value.value} değerini sil`} onClick={event => { event.stopPropagation(); void removeValue(item.attributeId, value.id) }}>×</button></span>)}</div>}</article>) : <Empty>Kategoriye ait özellik başlığı henüz eklenmedi.</Empty>}</div></article>
}

function CategoryAttributeWorkspace({ connectionId, localCategoryId, localCategories, localAttributes, onNotice }: { connectionId: string; localCategoryId: string; localCategories: LocalCategory[]; localAttributes: LocalAttribute[]; onNotice: (value: string) => void }) {
  const client = useQueryClient()
  const [attributeCategoryId, setAttributeCategoryId] = useState(localCategoryId)
  const categoryMappings = useQuery({ queryKey: ['category-mappings', connectionId], queryFn: () => hubApi<CatalogMapping[]>(`/mappings/categories?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId, retry: false })
  const matchedCategories = (categoryMappings.data ?? []).flatMap(mapping => {
    const category = localCategories.find(item => item.id === mapping.localId)
    return category ? [{ category, mapping }] : []
  })
  const matchedCategoryIds = matchedCategories.map(item => item.category.id).join(',')
  useEffect(() => {
    if (!matchedCategories.length) { if (attributeCategoryId) setAttributeCategoryId(''); return }
    if (!matchedCategories.some(item => item.category.id === attributeCategoryId)) setAttributeCategoryId(matchedCategories[0].category.id)
  }, [attributeCategoryId, matchedCategoryIds])
  useEffect(() => {
    if (localCategoryId && matchedCategories.some(item => item.category.id === localCategoryId)) setAttributeCategoryId(localCategoryId)
  }, [localCategoryId, matchedCategoryIds])
  const categoryRequirements = useQuery({ queryKey: ['category-requirements', attributeCategoryId, 'attribute-workspace'], queryFn: () => hubApi<CategoryRequirementView[]>(`/catalog/categories/${attributeCategoryId}/attribute-requirements`), enabled: !!attributeCategoryId })
  const categoryMapping = useQuery({ queryKey: ['category-mapping', attributeCategoryId, connectionId, 'embedded'], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/categories/${attributeCategoryId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!attributeCategoryId && !!connectionId, retry: false })
  const categoryScope = categoryMapping.data?.externalId ?? ''
  const references = useQuery({ queryKey: ['reference-attributes', connectionId, categoryScope, 'embedded'], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories/${encodeURIComponent(categoryScope)}/attributes?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId && !!categoryScope, retry: false })
  const sync = useMutation({ mutationFn: () => hubApi(`/connections/${connectionId}/reference-sync-jobs?resourceType=CATEGORY_ATTRIBUTES&parentExternalId=${encodeURIComponent(categoryScope)}`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: '{}' }), onSuccess: async () => { onNotice('Kategori özellikleri eşitleme kuyruğuna alındı.'); for (const delay of [500, 1000, 2000, 4000]) { await new Promise(resolve => window.setTimeout(resolve, delay)); await client.invalidateQueries({ queryKey: ['reference-attributes', connectionId, categoryScope, 'embedded'] }) } }, onError: reason => onNotice(reason instanceof Error ? reason.message : 'Kategori özellikleri eşitlenemedi.') })
  const mappings = useQuery({ queryKey: ['attribute-mappings', connectionId, categoryScope], queryFn: () => hubApi<CatalogMapping[]>(`/mappings/attributes?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(categoryScope)}`), enabled: !!connectionId && !!categoryScope, retry: false })
  const eligibleAttributes = localAttributes.filter(attribute => (categoryRequirements.data ?? []).some(req => req.attributeId === attribute.id))
  const mappingByExternal = new Map((mappings.data ?? []).map(item => [item.externalId, item]))
  const usedLocalIds = new Set((mappings.data ?? []).map(item => item.localId))
  const remoteItems = references.data?.items.filter(item => item.isActive).map(item => ({ ...item, name: displayAttributeName(item.name) })) ?? []
  const requiredItems = remoteItems.filter(item => item.isRequired === true)
  const mappedRequired = requiredItems.filter(item => mappingByExternal.has(item.externalId)).length
  if (!connectionId) return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>Önce 1. adımdaki kategori eşlemesini tamamlayın.</p></div></div><div className="unknown"><strong>Bağlantı seçilmedi</strong><p>Önce aktif Trendyol bağlantısını seçin.</p></div></article>
  if (categoryMappings.isLoading) return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>1. adımdaki eşleşmiş kategoriler hazırlanıyor.</p></div></div><Busy text="Kategori eşlemeleri yükleniyor…" /></article>
  if (!matchedCategories.length) return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>Yalnız 1. adımda eşleşen kategorilerin özellikleri burada açılır.</p></div></div><div className="unknown"><strong>Kategori eşlemesi bekleniyor</strong><p>Önce 1. adımda en az bir panel kategorisini Trendyol kategorisiyle eşleştirin.</p></div></article>
  if (!categoryMapping.data) return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>Sol taraftan merkezi ürün özelliğinizi seçin; ardından aynı karttan değer karşılıklarını eşleştirin.</p></div></div><div className="unknown"><strong>Kategori eşlemesi bekleniyor</strong><p>Önce 1. adımda panel kategorisini Trendyol kategorisiyle eşleştirin.</p></div></article>
  return <article className="panel mapping-step"><div className="editor-section-title"><span>3</span><div><h2>Trendyol kategori ve özellik eşlemeleri</h2><p>1. adımda eşleşen kategoriyi açın; ardından gerekli özellik karşılıklarını kaydedin.</p></div></div><label className="matched-category-select">Eşleşmiş panel kategorisi<select value={attributeCategoryId} onChange={event => setAttributeCategoryId(event.target.value)}>{matchedCategories.map(({ category }) => <option key={category.id} value={category.id}>{category.path}</option>)}</select></label>{references.isLoading || mappings.isLoading || categoryRequirements.isLoading ? <Busy text="Kategori özellikleri ve eşlemeler yükleniyor…" /> : references.isError || mappings.isError || categoryRequirements.isError ? <div className="unknown"><strong>Güncel kategori özellik verisi alınamadı</strong><p>Seçili Trendyol kategorisinin özellik listesini yeniden eşitleyin.</p><button type="button" disabled={sync.isPending} onClick={() => sync.mutate()}>{sync.isPending ? 'Kuyruğa alınıyor…' : 'Kategori özelliklerini eşitle'}</button></div> : <><div className={`mapping-progress ${mappedRequired === requiredItems.length ? 'complete' : ''}`}><strong>{mappedRequired}/{requiredItems.length} zorunlu alan eşlendi</strong><span>{remoteItems.length} toplam alan · {mappings.data?.length ?? 0} kayıtlı eşleme · Trendyol kategori no: {categoryScope}</span></div><div className="button-row"><button type="button" className="secondary" disabled={sync.isPending} onClick={() => sync.mutate()}>{sync.isPending ? 'Zorunlu alanlar yenileniyor…' : 'Zorunlu alanları Trendyol’dan yenile'}</button></div><div className="embedded-attribute-grid">{remoteItems.map(item => <CategoryAttributeCard key={item.externalId} connectionId={connectionId} categoryScope={categoryScope} snapshotId={references.data!.snapshotId} localAttributes={eligibleAttributes} remoteAttribute={item} existingMapping={mappingByExternal.get(item.externalId) ?? null} usedLocalIds={usedLocalIds} onNotice={onNotice} />)}</div></>}</article>
}

function CategoryAttributeCard({ connectionId, categoryScope, snapshotId, localAttributes, remoteAttribute, existingMapping, usedLocalIds, onNotice }: { connectionId: string; categoryScope: string; snapshotId: string; localAttributes: LocalAttribute[]; remoteAttribute: ReferenceItem; existingMapping: CatalogMapping | null; usedLocalIds: Set<string>; onNotice: (value: string) => void }) {
  const client = useQueryClient(); const [localId, setLocalId] = useState(existingMapping?.localId ?? ''); const [showValues, setShowValues] = useState(false)
  useEffect(() => { setLocalId(existingMapping?.localId ?? '') }, [existingMapping?.localId])
  const selectedAttribute = localAttributes.find(item => item.id === localId)
  const selectableAttributes = localAttributes.filter(item => item.id === localId || !usedLocalIds.has(item.id))
  async function save() {
    try {
      if (!localId) throw new Error('Entegrasyon ürün özelliğini seçin.')
      await hubApi<CatalogMapping>(`/mappings/attributes/${localId}`, { method: 'PUT', body: JSON.stringify({ connectionId, snapshotId, scopeExternalId: categoryScope, externalId: remoteAttribute.externalId, status: 'VERIFIED' }) })
      onNotice(`${remoteAttribute.name} eşlemesi kaydedildi.`)
      await client.invalidateQueries({ queryKey: ['attribute-mappings', connectionId, categoryScope] })
    } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Özellik eşlemesi kaydedilemedi.') }
  }
  async function remove() {
    if (!existingMapping) return
    try {
      await hubApi<boolean>(`/mappings/attributes/${existingMapping.localId}?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(categoryScope)}`, { method: 'DELETE', headers: { 'If-Match': `"v${existingMapping.version}"` } })
      setShowValues(false); onNotice(`${remoteAttribute.name} eşlemesi kaldırıldı.`)
      await client.invalidateQueries({ queryKey: ['attribute-mappings', connectionId, categoryScope] })
    } catch (reason) { onNotice(reason instanceof Error ? reason.message : 'Özellik eşlemesi kaldırılamadı.') }
  }
  const mapped = existingMapping?.externalId === remoteAttribute.externalId
  const required = remoteAttribute.isRequired === true
  return <section className={`attribute-mapping-card ${required ? 'required' : ''} ${required && !mapped ? 'unmapped' : ''}`}><div className="attribute-mapping-card-head"><span className="attr-source">TY</span><div><strong>{remoteAttribute.name}</strong><small>{required ? 'Zorunlu alan' : ''}{mapped ? ' · eşlendi' : ''}</small></div></div><div className="mapping-fields compact"><label>Entegrasyon ürün özelliği<select value={localId} onChange={event => setLocalId(event.target.value)} disabled={mapped}><option value="">Özellik seçin</option>{selectableAttributes.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{mapped ? <button type="button" className="secondary" onClick={() => void remove()}>Eşlemeyi kaldır</button> : <button type="button" onClick={() => void save()} disabled={!localId}>Kaydet</button>}</div>{selectedAttribute && mapped && selectedAttribute.values.length > 0 && <><button type="button" className="value-mapping-toggle" onClick={() => setShowValues(value => !value)}>{showValues ? 'Değer eşlemelerini gizle' : `Değer eşlemelerini aç (${selectedAttribute.values.length})`}</button>{showValues && <AttributeValueMappingEditor connectionId={connectionId} categoryScope={categoryScope} attribute={selectedAttribute} externalAttributeId={remoteAttribute.externalId} />}</>}</section>
}

export function AttributeMappingPage() {
  const client = useQueryClient(); const [connectionId, setConnectionId] = useState(''); const [categoryId, setCategoryId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'attribute-mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const categories = useQuery({ queryKey: ['categories', 'attribute-mapping'], queryFn: () => hubApi<Page<LocalCategory>>('/catalog/categories?limit=200') })
  const localAttributes = useQuery({ queryKey: ['attributes', 'mapping'], queryFn: () => hubApi<Page<LocalAttribute>>('/catalog/attributes?limit=200') })
  const categoryMapping = useQuery({ queryKey: ['category-mapping', categoryId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/categories/${categoryId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!categoryId && !!connectionId, retry: false })
  const categoryScope = categoryMapping.data?.externalId ?? ''
  const references = useQuery({ queryKey: ['reference-attributes', connectionId, categoryScope], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories/${encodeURIComponent(categoryScope)}/attributes?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId && !!categoryScope, retry: false })
  const mapping = useQuery({ queryKey: ['attribute-mapping', localId, connectionId, categoryScope], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/attributes/${localId}?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(categoryScope)}`), enabled: !!localId && !!connectionId && !!categoryScope, retry: false })
  const sync = useMutation({ mutationFn: () => hubApi(`/connections/${connectionId}/reference-sync-jobs?resourceType=CATEGORY_ATTRIBUTES&parentExternalId=${encodeURIComponent(categoryScope)}`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: '{}' }), onSuccess: () => setNotice('Kategori özellikleri salt-okunur eşitleme kuyruğuna alındı.'), onError: reason => setNotice(reason instanceof Error ? reason.message : 'Özellik eşitleme başlatılamadı.') })
  const save = useMutation({ mutationFn: () => {
    if (!references.data || !localId || !externalId) throw new Error('Bağlantı, kategori, panel özelliği ve Trendyol özelliği zorunludur.')
    return hubApi<CatalogMapping>(`/mappings/attributes/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, scopeExternalId: categoryScope, externalId, status: 'VERIFIED' }) })
  }, onSuccess: async value => { setNotice('Özellik eşlemesi doğrulandı ve kategori kapsamında kaydedildi.'); setExternalId(value.externalId); await client.invalidateQueries({ queryKey: ['attribute-mapping', localId, connectionId, categoryScope] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Özellik eşlemesi kaydedilemedi.') })
  useEffect(() => { if (mapping.data) setExternalId(mapping.data.externalId) }, [mapping.data])
  const activeConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []; const localLeaves = categories.data?.items.filter(item => item.isActive && item.isLeaf) ?? []; const activeAttributes = localAttributes.data?.items.filter(item => item.isActive) ?? []; const remoteAttributes = references.data?.items.filter(item => item.isActive) ?? []
  return <section className="content f3 mapping-page"><div className="page-heading"><div><p className="eyebrow">Eşleştirme ayarları</p><h1>Özellik eşlemeleri</h1><p className="lede">Yerel özellikleri güncel Trendyol V2 kategori özelliği snapshot’ına kategori kapsamında eşleyin.</p></div><Badge value="SAFE READ" /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="button-row"><Link className="button-link secondary" to="/mappings/categories">Kategoriler</Link><Link className="button-link secondary" to="/mappings/categories?view=brands">Markalar</Link><Link className="button-link" to="/mappings/attributes">Özellikler</Link></div>
    <article className="panel mapping-step"><div className="editor-section-title"><span>1</span><div><h2>Kategori kapsamını seçin</h2><p>Özellik kimlikleri seçili ve doğrulanmış Trendyol yaprak kategorisi kapsamında tutulur.</p></div></div><div className="mapping-fields"><label>Özellik için aktif Trendyol bağlantısı<select aria-label="Özellik için aktif Trendyol bağlantısı" value={connectionId} onChange={event => { setConnectionId(event.target.value); setCategoryId(''); setLocalId(''); setExternalId(''); setNotice('') }}><option value="">Bağlantı seçin</option>{activeConnections.map(item => <option value={item.id} key={item.id}>{item.displayName} · {item.externalStoreId}</option>)}</select></label><label>Panel yaprak kategorisi<select aria-label="Özellik kapsamı panel kategorisi" value={categoryId} onChange={event => { setCategoryId(event.target.value); setLocalId(''); setExternalId(''); setNotice('') }} disabled={!connectionId}><option value="">Kategori seçin</option>{localLeaves.map(item => <option value={item.id} key={item.id}>{item.path}</option>)}</select></label></div>
      {categoryId && !categoryMapping.isLoading && !categoryMapping.data ? <div className="unknown"><strong>Kategori eşlemesi gerekli</strong><p>Özellikleri almadan önce panel kategorisini Trendyol yaprak kategorisiyle eşleyin.</p><Link className="button-link" to="/mappings/categories">Kategori eşlemelerine git</Link></div> : categoryScope && references.isError ? <div className="unknown"><strong>Güncel özellik snapshot’ı yok</strong><p>Seçili kategori için yalnız salt-okunur özellik listesini eşitleyin.</p><button disabled={sync.isPending} onClick={() => sync.mutate()}>{sync.isPending ? 'Kuyruğa alınıyor…' : 'Kategori özelliklerini eşitle'}</button></div> : null}</article>
    {references.data && <article className="panel mapping-step"><div className="editor-section-title"><span>2</span><div><h2>Özelliği eşleyin</h2><p>Bu işlem yalnız yerel mapping kaydı oluşturur; Trendyol’a yazmaz.</p></div></div><div className="mapping-fields"><label>Panel özelliği<select aria-label="Panel özelliği" value={localId} onChange={event => { setLocalId(event.target.value); setExternalId(''); setNotice('') }}><option value="">Özellik seçin</option>{activeAttributes.map(item => <option value={item.id} key={item.id}>{item.name} · {item.dataType}</option>)}</select></label><label>Trendyol kategori özelliği<select aria-label="Trendyol kategori özelliği" value={externalId} onChange={event => setExternalId(event.target.value)} disabled={!localId || mapping.isLoading}><option value="">Özellik seçin</option>{remoteAttributes.map(item => <option value={item.externalId} key={item.externalId}>{item.name}{item.isRequired ? ' · zorunlu' : ''}{item.allowsCustomValue ? ' · serbest değer' : ''}</option>)}</select></label></div><div className="mapping-action"><span>{remoteAttributes.length.toLocaleString('tr-TR')} özellik · kategori {categoryScope}{mapping.data ? ` · mevcut eşleme v${mapping.data.version}` : ''}</span><button disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Kaydediliyor…' : mapping.data ? 'Eşlemeyi güncelle' : 'Eşlemeyi doğrula ve kaydet'}</button></div>{mapping.data && localId && <AttributeValueMappingEditor connectionId={connectionId} categoryScope={categoryScope} attribute={activeAttributes.find(item => item.id === localId)!} externalAttributeId={mapping.data.externalId} />}</article>}
  </section>
}

function AttributeValueMappingEditor({ connectionId, categoryScope, attribute, externalAttributeId }: { connectionId: string; categoryScope: string; attribute: LocalAttribute; externalAttributeId: string }) {
  const client = useQueryClient(); const [notice, setNotice] = useState(''); const [selections, setSelections] = useState<Record<string, string>>({}); const [saving, setSaving] = useState(false); const valueScope = `${categoryScope}/${externalAttributeId}`
  const references = useQuery({ queryKey: ['reference-attribute-values', connectionId, valueScope], queryFn: () => hubApi<ReferenceData>(`/reference-data/categories/${encodeURIComponent(categoryScope)}/attributes/${encodeURIComponent(externalAttributeId)}/values?connectionId=${encodeURIComponent(connectionId)}`), retry: false })
  const mappings = useQuery({ queryKey: ['attribute-value-mappings', connectionId, valueScope], queryFn: () => hubApi<CatalogMapping[]>(`/mappings/attribute-values?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(valueScope)}`), retry: false })
  const sync = useMutation({ mutationFn: () => hubApi(`/connections/${connectionId}/reference-sync-jobs?resourceType=ATTRIBUTE_VALUES&parentExternalId=${encodeURIComponent(valueScope)}`, { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: '{}' }), onSuccess: () => setNotice('Özellik değerleri salt-okunur eşitleme kuyruğuna alındı.'), onError: reason => setNotice(reason instanceof Error ? reason.message : 'Değer eşitleme başlatılamadı.') })
  const localValues = attribute.values?.filter(item => item.isActive) ?? []; const remoteValues = references.data?.items.filter(item => item.isActive) ?? []; const mappingByLocal = new Map((mappings.data ?? []).map(item => [item.localId, item]))
  useEffect(() => { if (mappings.data) setSelections(Object.fromEntries(mappings.data.map(item => [item.localId, item.externalId]))) }, [mappings.data])
  async function saveAll() {
    if (!references.data) return
    const chosen = Object.values(selections).filter(Boolean)
    if (new Set(chosen).size !== chosen.length) return setNotice('Aynı Trendyol değeri birden fazla panel değerine eşlenemez.')
    setSaving(true); setNotice('')
    try {
      var changed = 0
      for (const localValue of localValues) {
        const externalId = selections[localValue.id] ?? ''
        const existing = mappingByLocal.get(localValue.id)
        if (!externalId && existing) {
          await hubApi<boolean>(`/mappings/attribute-values/${localValue.id}?connectionId=${encodeURIComponent(connectionId)}&scopeExternalId=${encodeURIComponent(valueScope)}`, { method: 'DELETE', headers: { 'If-Match': `"v${existing.version}"` } })
          changed++
          continue
        }
        if (!externalId || existing?.externalId === externalId) continue
        await hubApi<CatalogMapping>(`/mappings/attribute-values/${localValue.id}`, { method: 'PUT', headers: existing ? { 'If-Match': `"v${existing.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, scopeExternalId: valueScope, externalId, status: 'VERIFIED' }) })
        changed++
      }
      await client.invalidateQueries({ queryKey: ['attribute-value-mappings', connectionId, valueScope] })
      setNotice(changed ? `${changed} değer eşlemesi kaydedildi.` : 'Değer eşlemelerinde değişiklik yok.')
    } catch (reason) { setNotice(reason instanceof Error ? reason.message : 'Değer eşlemeleri kaydedilemedi.') } finally { setSaving(false) }
  }
  if (!localValues.length) return <div className="unknown"><strong>Serbest değer özelliği</strong><p>Bu yerel özellik seçim listesi taşımıyor; Trendyol özelliği serbest değer kabul etmiyorsa yayınlama kapısı işlemi reddeder.</p></div>
  if (references.isError) return <div className="unknown"><strong>Güncel özellik değerleri snapshot’ı yok</strong><p>Seçili kategori ve özellik için salt-okunur değer listesini eşitleyin.</p>{notice && <p role="status">{notice}</p>}<button disabled={sync.isPending} onClick={() => sync.mutate()}>{sync.isPending ? 'Kuyruğa alınıyor…' : 'Özellik değerlerini eşitle'}</button></div>
  if (references.isLoading || mappings.isLoading) return <Busy text="Özellik değerleri ve mevcut eşlemeler yükleniyor…" />
  if (mappings.isError) return <ErrorBox error={mappings.error} />
  const used = new Set(Object.values(selections).filter(Boolean))
  return <div className="mapping-step nested value-mapping-editor"><div className="value-mapping-heading"><div><h3>Değer eşleştirmeleri</h3><p>{localValues.length} panel değeri · {remoteValues.length} Trendyol değeri</p></div><button type="button" disabled={saving} onClick={() => void saveAll()}>{saving ? 'Kaydediliyor…' : 'Tüm eşlemeleri kaydet'}</button></div>{notice && <p role="status" className="notice">{notice}</p>}<div className="value-mapping-rows">{localValues.map(localValue => <label key={localValue.id} className="value-mapping-row"><span>{localValue.value}</span><b>→</b><select aria-label={`${localValue.value} Trendyol değeri`} value={selections[localValue.id] ?? ''} onChange={event => setSelections(current => ({ ...current, [localValue.id]: event.target.value }))}><option value="">Trendyol değeri seçin</option>{remoteValues.map(remote => <option key={remote.externalId} value={remote.externalId} disabled={used.has(remote.externalId) && selections[localValue.id] !== remote.externalId}>{remote.name}</option>)}</select><small>{mappingByLocal.has(localValue.id) ? 'Eşlendi' : 'Bekliyor'}</small></label>)}</div></div>
}

export function BrandMappingPage() {
  const client = useQueryClient(); const [connectionId, setConnectionId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState(''); const [brandName, setBrandName] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'brand-mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const localBrands = useQuery({ queryKey: ['brands', 'mapping'], queryFn: () => hubApi<Page<LocalBrand>>('/catalog/brands?limit=200') })
  const references = useQuery({ queryKey: ['reference-brands', connectionId], queryFn: () => hubApi<ReferenceData>(`/reference-data/brands?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId, retry: false })
  const mapping = useQuery({ queryKey: ['brand-mapping', localId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/brands/${localId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!localId && !!connectionId, retry: false })
  const save = useMutation({ mutationFn: () => { if (!references.data || !localId || !externalId) throw new Error('Bağlantı, panel markası ve Trendyol markası zorunludur.'); return hubApi<CatalogMapping>(`/mappings/brands/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) }) }, onSuccess: async value => { setNotice('Marka eşlemesi doğrulandı ve kaydedildi.'); setExternalId(value.externalId); await client.invalidateQueries({ queryKey: ['brand-mapping', localId, connectionId] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Eşleme kaydedilemedi.') })
  const createBrand = useMutation({ mutationFn: () => { if (!brandName.trim()) throw new Error('Marka adı zorunludur.'); return hubApi<LocalBrand>('/catalog/brands', { method: 'POST', headers: { 'Idempotency-Key': idempotency() }, body: JSON.stringify({ name: brandName.trim() }) }) }, onSuccess: async brand => { await client.invalidateQueries({ queryKey: ['brands', 'mapping'] }); setLocalId(brand.id); setExternalId(''); setBrandName(''); setNotice(`“${brand.name}” panel markası oluşturuldu ve seçildi.`) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Marka oluşturulamadı.') })
  useEffect(() => { setExternalId(mapping.data?.externalId ?? '') }, [mapping.data])
  const trendyolConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []
  useEffect(() => { if (!connectionId && trendyolConnections.length) setConnectionId(trendyolConnections[0].id) }, [connectionId, trendyolConnections])
  const activeLocalBrands = localBrands.data?.items.filter(item => item.isActive) ?? []
  const externalBrands = references.data?.items.filter(item => item.isActive) ?? []
  const archiveBrand = useMutation({ mutationFn: (brand: LocalBrand) => hubApi<LocalBrand>(`/catalog/brands/${brand.id}`, { method: 'PATCH', headers: { 'If-Match': `"v${brand.version}"` }, body: JSON.stringify({ name: brand.name, isActive: false }) }), onSuccess: async (_, brand) => { if (localId === brand.id) { setLocalId(''); setExternalId('') }; await client.invalidateQueries({ queryKey: ['brands', 'mapping'] }); setNotice(`“${brand.name}” panel markalarından kaldırıldı.`) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Marka kaldırılamadı.') })
  return <section className="content f3 mapping-page mapping-workspace"><div className="mapping-workspace-heading"><div><p className="eyebrow">Merkezi katalog sistemi</p><h1>Eşleştirme Merkezi</h1></div></div><MappingViewTabs active="brand" />{notice && <div role="status" className="notice">{notice}</div>}
    <article className="panel mapping-console">
      <form className="platform-category-create" onSubmit={event => { event.preventDefault(); createBrand.mutate() }}><label>Yeni panel markası<input aria-label="Yeni panel markası adı" maxLength={160} value={brandName} onChange={event => setBrandName(event.target.value)} placeholder="Örn. Ravencia" required /></label><button disabled={createBrand.isPending}>{createBrand.isPending ? 'Ekleniyor…' : '+ Marka ekle'}</button></form><div className="category-chip-list" aria-label="Eklenen panel markaları">{activeLocalBrands.length ? activeLocalBrands.map(brand => <span key={brand.id} className={brand.id === localId ? 'active' : ''}><button type="button" onClick={() => { setLocalId(brand.id); setExternalId(''); setNotice('') }}>{brand.name}</button><button type="button" className="category-chip-remove" aria-label={`${brand.name} markasını kaldır`} onClick={() => archiveBrand.mutate(brand)} disabled={archiveBrand.isPending}>×</button></span>) : <small>Henüz panel markası eklenmedi.</small>}</div>
      <div className="mapping-pair-grid"><section className="mapping-side local"><div className="mapping-side-head"><span>Panel kataloğu</span><strong>Panel markası</strong><small>Ürünlerinizde kullandığınız yerel markayı seçin.</small></div><SearchableSelect label="Panel markası" value={localId} options={activeLocalBrands.map(item => ({ value: item.id, label: item.name, description: 'Panel markası' }))} placeholder="Panel markalarında ara" disabled={!connectionId} onChange={value => { setLocalId(value); setExternalId(''); setNotice('') }} /></section><div className="mapping-link-rail" aria-hidden="true"><span>⇄</span><small>Eşleştir</small></div><section className="mapping-side remote"><div className="mapping-side-head"><span>Trendyol kataloğu</span><strong>Trendyol markası</strong><small>Güncel referans listesindeki marka karşılığını seçin.</small></div><SearchableSelect label="Trendyol markası" value={externalId} options={externalBrands.map(item => ({ value: item.externalId, label: item.name, description: `Trendyol marka no: ${item.externalId}` }))} placeholder={references.isLoading ? 'Markalar yükleniyor…' : 'Marka adı veya marka no ara'} disabled={!localId || references.isLoading || references.isError} onChange={setExternalId} /></section></div>
      {connections.isError || localBrands.isError ? <ErrorBox error={connections.error ?? localBrands.error} /> : references.isError ? <div className="unknown"><strong>Güncel marka listesi yok</strong><p>Bağlantı ekranından “Markaları eşitle” işlemini çalıştırın.</p><Link className="button-link" to={`/integrations/${connectionId}`}>Bağlantıya git</Link></div> : connectionId && references.data ? <div className="mapping-action"><span><strong>{externalBrands.length.toLocaleString('tr-TR')}</strong> marka · {new Date(references.data.fetchedAt).toLocaleString('tr-TR')}{mapping.data ? ` · Kayıt v${mapping.data.version}` : ''}</span><button type="button" disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Kaydediliyor…' : mapping.data ? 'Eşleştirmeyi güncelle' : 'Eşleştirmeyi kaydet'}</button></div> : null}
    </article></section>
}

function LegacyBrandMappingPage() {
  const client = useQueryClient(); const [connectionId, setConnectionId] = useState(''); const [localId, setLocalId] = useState(''); const [externalId, setExternalId] = useState(''); const [notice, setNotice] = useState('')
  const connections = useQuery({ queryKey: ['connections', 'brand-mapping'], queryFn: () => hubApi<Page<Connection>>('/connections?limit=200') })
  const localBrands = useQuery({ queryKey: ['brands', 'mapping'], queryFn: () => hubApi<Page<LocalBrand>>('/catalog/brands?limit=200') })
  const references = useQuery({ queryKey: ['reference-brands', connectionId], queryFn: () => hubApi<ReferenceData>(`/reference-data/brands?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!connectionId, retry: false })
  const mapping = useQuery({ queryKey: ['brand-mapping', localId, connectionId], queryFn: () => hubApi<CatalogMapping | null>(`/mappings/brands/${localId}?connectionId=${encodeURIComponent(connectionId)}`), enabled: !!localId && !!connectionId, retry: false })
  const save = useMutation({ mutationFn: () => {
    if (!references.data || !localId || !externalId) throw new Error('Bağlantı, panel markası ve Trendyol markası zorunludur.')
    return hubApi<CatalogMapping>(`/mappings/brands/${localId}`, { method: 'PUT', headers: mapping.data ? { 'If-Match': `"v${mapping.data.version}"` } : {}, body: JSON.stringify({ connectionId, snapshotId: references.data.snapshotId, externalId, status: 'VERIFIED' }) })
  }, onSuccess: async value => { setNotice('Marka eşlemesi doğrulandı ve kaydedildi.'); setExternalId(value.externalId); await client.invalidateQueries({ queryKey: ['brand-mapping', localId, connectionId] }) }, onError: reason => setNotice(reason instanceof Error ? reason.message : 'Eşleme kaydedilemedi.') })
  useEffect(() => { setExternalId(mapping.data?.externalId ?? '') }, [mapping.data])
  const trendyolConnections = connections.data?.items.filter(item => item.platformCode === 'TRENDYOL' && item.status === 'ACTIVE') ?? []
  const activeLocalBrands = localBrands.data?.items.filter(item => item.isActive) ?? []
  const externalBrands = references.data?.items.filter(item => item.isActive) ?? []

  return <section className="content f3 mapping-page"><div className="page-heading"><div><p className="eyebrow">Eşleştirme ayarları</p><h1>Marka eşlemeleri</h1><p className="lede">Yerel markayı doğrulanmış Trendyol marka snapshot’ındaki kimlikle eşleştirin.</p></div><Badge value="SAFE READ" /></div>{notice && <div role="status" className="notice">{notice}</div>}
    <div className="button-row"><Link className="button-link secondary" to="/mappings/categories">Kategoriler</Link><Link className="button-link" to="/mappings/categories?view=brands">Markalar</Link><Link className="button-link secondary" to="/mappings/attributes">Özellikler</Link></div>
    <article className="panel mapping-step"><div className="editor-section-title"><span>1</span><div><h2>Trendyol marka eşlemesi</h2><p>Bu işlem yalnız yerel mapping kaydı oluşturur; Trendyol’a veri göndermez.</p></div></div>
      <div className="mapping-fields"><label>Aktif Trendyol bağlantısı<select aria-label="Marka için aktif Trendyol bağlantısı" value={connectionId} onChange={event => { setConnectionId(event.target.value); setLocalId(''); setExternalId(''); setNotice('') }}><option value="">Bağlantı seçin</option>{trendyolConnections.map(item => <option value={item.id} key={item.id}>{item.displayName} · {item.externalStoreId}</option>)}</select></label>
        <label>Panel markası<select aria-label="Panel markası" value={localId} onChange={event => { setLocalId(event.target.value); setExternalId(''); setNotice('') }} disabled={!connectionId}><option value="">Marka seçin</option>{activeLocalBrands.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>
        <label>Trendyol markası<select aria-label="Trendyol markası" value={externalId} onChange={event => setExternalId(event.target.value)} disabled={!localId || references.isLoading || references.isError}><option value="">Marka seçin</option>{externalBrands.map(item => <option value={item.externalId} key={item.externalId}>{item.name}</option>)}</select></label></div>
      {connections.isError || localBrands.isError ? <ErrorBox error={connections.error ?? localBrands.error} /> : references.isError ? <div className="unknown"><strong>Güncel marka snapshot’ı yok</strong><p>Bağlantı ekranından “Markaları eşitle” işlemini çalıştırın.</p><Link className="button-link" to={`/integrations/${connectionId}`}>Bağlantıya git</Link></div> : references.isLoading ? <Busy text="Marka snapshot’ı yükleniyor…" /> : connectionId && references.data ? <div className="mapping-action"><span>{externalBrands.length.toLocaleString('tr-TR')} marka · snapshot {new Date(references.data.fetchedAt).toLocaleString('tr-TR')}{mapping.data ? ` · mevcut eşleme v${mapping.data.version}` : ''}</span><button type="button" disabled={!localId || !externalId || save.isPending || mapping.isLoading} onClick={() => save.mutate()}>{save.isPending ? 'Kaydediliyor…' : mapping.data ? 'Eşlemeyi güncelle' : 'Eşlemeyi doğrula ve kaydet'}</button></div> : null}
    </article></section>
}

function ListPage({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children: React.ReactNode }) { return <section className="content f3"><div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="lede">{description}</p></div><Badge value="LIVE READ" /></div><div className="panel">{children}</div></section> }
